import{s as e}from"./appStore-DYtKKg5i.js";var t=Object.assign({"../../../content/phrases/A1.ts":[{id:`nice-to-meet-you`,level:`A1`,topic:`Знакомство`,expression:`Nice to meet you`,literal:`приятно встретить тебя`,meaning:`вежливая фраза при первом знакомстве`,equivalent:`приятно познакомиться`,register:`neutral`,examples:[[`Hi, I’m Kate. — Nice to meet you, Kate. I’m Ivan.`,`Привет, я Кейт. — Приятно познакомиться, Кейт. Я Иван.`]],mistake:`Только при первой встрече. Знакомым при новой встрече говорят Nice to see you.`},{id:`how-are-you`,level:`A1`,topic:`Приветствие`,expression:`How are you?`,literal:`как ты есть?`,meaning:`приветствие с вопросом о самочувствии; подробного рассказа не ждут`,equivalent:`как дела?`,register:`neutral`,examples:[[`Hi, Tom! How are you? — Fine, thanks.`,`Привет, Том! Как дела? — Хорошо, спасибо.`]],mistake:`Это скорее приветствие: отвечают коротко, например Fine, thanks. And you?`},{id:`fine-thanks`,level:`A1`,topic:`Приветствие`,expression:`Fine, thanks. And you?`,literal:`прекрасно, спасибо. И ты?`,meaning:`стандартный короткий ответ на How are you? со встречным вопросом`,equivalent:`хорошо, спасибо. А у вас?`,register:`neutral`,examples:[[`How are you? — Fine, thanks. And you?`,`Как дела? — Хорошо, спасибо. А у вас?`]],mistake:`Встречный вопрос And you? — вежливая привычка: без него ответ звучит суховато.`},{id:`where-are-you-from`,level:`A1`,topic:`Знакомство`,expression:`Where are you from?`,literal:`где ты из?`,meaning:`вопрос о родной стране или городе`,equivalent:`откуда вы?`,register:`neutral`,examples:[[`Where are you from? — I’m from Russia.`,`Откуда вы? — Я из России.`]],mistake:`Предлог from стоит в конце вопроса: не From where are you?`},{id:`excuse-me`,level:`A1`,topic:`Вежливость`,expression:`Excuse me`,literal:`извини меня`,meaning:`вежливо привлечь внимание незнакомого человека, начать вопрос или попросить пропустить`,equivalent:`извините, простите (можно вас?)`,register:`neutral`,examples:[[`Excuse me, what is this in English? — It’s a key.`,`Извините, как это по-английски? — Это ключ.`]],mistake:`Чтобы обратиться к человеку, говорят Excuse me. Sorry — это извинение за ошибку: Sorry, I’m late.`},{id:`here-you-are`,level:`A1`,topic:`Просьбы`,expression:`Here you are`,literal:`здесь ты есть`,meaning:`фраза, когда вы протягиваете человеку вещь`,equivalent:`вот, пожалуйста; держите`,register:`neutral`,examples:[[`Is this your pen? — Yes, it is. — Here you are.`,`Это ваша ручка? — Да. — Вот, держите.`]],mistake:`Протягивая вещь, не говорят Please: русское «пожалуйста» здесь переводится как Here you are. В американской разговорной речи часто говорят и Here you go.`},{id:`thank-you-so-much`,level:`A1`,topic:`Вежливость`,expression:`Thank you so much`,literal:`спасибо тебе так много`,meaning:`тёплая, искренняя благодарность`,equivalent:`большое спасибо`,register:`neutral`,examples:[[`Here you are. — Thank you so much!`,`Вот, держите. — Большое спасибо!`]],mistake:`Нельзя сказать Thank you much — нужно so much или very much.`},{id:`youre-welcome`,level:`A1`,topic:`Вежливость`,expression:`You’re welcome`,literal:`ты желанный`,meaning:`вежливый ответ на благодарность`,equivalent:`пожалуйста; не за что`,register:`neutral`,examples:[[`Thank you so much! — You’re welcome.`,`Большое спасибо! — Пожалуйста.`]],mistake:`На Thank you не отвечают Please: русское «пожалуйста» здесь — You’re welcome.`},{id:`what-is-this-in-english`,level:`A1`,topic:`Просьбы`,expression:`What is this in English?`,literal:`что есть это на английском?`,meaning:`спросить, как называется предмет по-английски`,equivalent:`как это по-английски?`,register:`neutral`,examples:[[`What is this in English? — It’s an umbrella.`,`Как это по-английски? — Это зонт.`]],mistake:`Дословно «Как это по-английски?» — How is it in English? — так не говорят. Верно: What is this in English? или How do you say this in English?`},{id:`this-is-my`,level:`A1`,topic:`Знакомство`,expression:`This is my…`,literal:`это есть мой…`,meaning:`так представляют одного человека другому: друга, родственника, коллегу`,equivalent:`познакомьтесь, это мой…`,register:`neutral`,examples:[[`Mom, this is Kate. Kate, this is my mom.`,`Мама, это Кейт. Кейт, познакомься, это моя мама.`],[`This is my brother, Max.`,`Познакомьтесь, это мой брат Макс.`]],mistake:`Представляя человека, говорят This is…, а не He is… или It is… О двоих — These are my parents.`},{id:`say-hi-to`,level:`A1`,topic:`Прощание`,expression:`Say hi to…`,literal:`скажи привет к…`,meaning:`просьба передать кому-то привет`,equivalent:`передай привет…`,register:`informal`,examples:[[`Bye, Anna! Say hi to your mom for me.`,`Пока, Анна! Передай от меня привет маме.`]],mistake:`После hi нужен предлог to: say hi to your mom, не say hi your mom. Не переводите «передай привет» дословно: give hi и pass hello не говорят.`},{id:`see-you-later`,level:`A1`,topic:`Прощание`,expression:`See you later!`,literal:`увижу тебя позже`,meaning:`дружеское прощание; не обязательно значит, что вы встретитесь сегодня`,equivalent:`пока, до встречи`,register:`informal`,examples:[[`Bye, Tom! — See you later!`,`Пока, Том! — До встречи!`]],mistake:`Не See you late: later — «позже», late — «поздно».`},{id:`take-care`,level:`A1`,topic:`Прощание`,expression:`Take care!`,literal:`возьми заботу`,meaning:`тёплое прощание с пожеланием всего хорошего`,equivalent:`береги себя; всего доброго`,register:`neutral`,examples:[[`Bye, Grandma! — Bye, my dear. Take care!`,`Пока, бабушка! — Пока, дорогой. Береги себя!`]],mistake:`Не Take care of you: просто Take care! или полностью Take care of yourself!`},{id:`come-in`,level:`A1`,topic:`Гости`,expression:`Come in!`,literal:`приходи внутрь!`,meaning:`приглашение войти в дом или в комнату`,equivalent:`входите! проходите!`,register:`neutral`,examples:[[`Hi, Mark! Come in! — Thanks.`,`Привет, Марк! Проходи! — Спасибо.`],[`Come in, please. The living room is on the left.`,`Проходите, пожалуйста. Гостиная слева.`]],mistake:`«Проходите» — не Pass: pass значит «пропустить» или «передать». Гостям говорят Come in.`},{id:`have-a-seat`,level:`A1`,topic:`Гости`,expression:`Have a seat`,literal:`имей сиденье`,meaning:`вежливое предложение сесть`,equivalent:`присаживайтесь, садитесь`,register:`neutral`,examples:[[`Have a seat. There’s a chair next to the window.`,`Присаживайтесь. Рядом с окном есть стул.`]],mistake:`Seat — «сиденье, место», а не глагол sit: не have a sit. Просто Sit down! без please звучит как приказ.`},{id:`make-yourself-at-home`,level:`A1`,topic:`Гости`,expression:`Make yourself at home`,literal:`сделай себя дома`,meaning:`хозяин просит гостя чувствовать себя свободно и не стесняться`,equivalent:`будьте как дома, чувствуйте себя как дома`,register:`neutral`,examples:[[`Come in and make yourself at home. The bathroom is next to the kitchen.`,`Проходите и будьте как дома. Ванная рядом с кухней.`]],mistake:`Не Be like at home и не Feel like at home: устойчивая форма — Make yourself at home.`},{id:`help-yourself`,level:`A1`,topic:`Гости`,expression:`Help yourself`,literal:`помоги себе`,meaning:`предложение гостю брать угощение самому, сколько хочется`,equivalent:`угощайтесь, берите`,register:`neutral`,examples:[[`There are some cookies on the table. Help yourself!`,`На столе печенье. Угощайтесь!`]],mistake:`Это не просьба о помощи, а «угощайтесь». Treat yourself значит «побалуйте себя», гостю за столом так не говорят.`},{id:`are-you-ok`,level:`A1`,topic:`Самочувствие`,expression:`Are you OK?`,literal:`ты есть ОК?`,meaning:`участливый вопрос, когда человек выглядит расстроенным, уставшим или больным`,equivalent:`ты в порядке? / всё хорошо?`,register:`neutral`,examples:[[`You look tired. Are you OK? — Yes, I’m fine, thanks.`,`Ты какой-то уставший. Всё в порядке? — Да, всё хорошо, спасибо.`]],mistake:`Не путайте с How are you?: Are you OK? спрашивают, когда что-то, похоже, не так. Пишется и OK, и okay.`},{id:`not-bad`,level:`A1`,topic:`Самочувствие`,expression:`Not bad`,literal:`не плохой`,meaning:`ответ на How are you?: дела идут нормально, скорее хорошо`,equivalent:`неплохо, нормально`,register:`informal`,examples:[[`How are you? — Not bad, thanks. And you?`,`Как дела? — Неплохо, спасибо. А у тебя?`]],mistake:`Отрицание здесь — not, а не no: не No bad. Если дела правда плохи, говорят Not great.`},{id:`whats-wrong`,level:`A1`,topic:`Чувства`,expression:`What’s wrong?`,literal:`что есть неправильно?`,meaning:`вопрос, когда видно, что человек расстроен, болен или чем-то обеспокоен`,equivalent:`что случилось? / в чём дело?`,register:`neutral`,examples:[[`What’s wrong? — I’m sick.`,`Что случилось? — Я заболел.`],[`You look sad. What’s wrong?`,`Ты какой-то грустный. Что случилось?`]],mistake:`Дословный перевод «Что случилось?» — What happened? — спрашивает о конкретном событии. Если человек просто выглядит грустным или больным, естественнее What’s wrong?`},{id:`im-not-sure`,level:`A1`,topic:`Реакции`,expression:`I’m not sure`,literal:`я не есть уверенный`,meaning:`мягкий ответ, когда вы не знаете точно`,equivalent:`не знаю точно; не уверен`,register:`neutral`,examples:[[`Is Tom at home? — I’m not sure.`,`Том дома? — Не знаю точно.`]],mistake:`Без to be нельзя: не I not sure, а I’m not sure.`},{id:`time-to-get-up`,level:`A1`,topic:`Распорядок дня`,expression:`Time to get up!`,literal:`время к встать вверх!`,meaning:`утренний призыв встать с постели; time to + глагол — «пора что-то делать»`,equivalent:`пора вставать!`,register:`informal`,examples:[[`It’s seven o’clock! Time to get up!`,`Уже семь часов! Пора вставать!`],[`Time to get up! — Five more minutes, Mom!`,`Пора вставать! — Ещё пять минуток, мам!`]],mistake:`Не Hour to get up: «пора» — time. По той же схеме: Time to go! Time for bed!`},{id:`have-a-good-day`,level:`A1`,topic:`Распорядок дня`,expression:`Have a good day!`,literal:`имей хороший день!`,meaning:`пожелание при прощании утром или днём`,equivalent:`хорошего дня!`,register:`neutral`,examples:[[`Bye, Mom! — Bye! Have a good day!`,`Пока, мам! — Пока! Хорошего дня!`],[`Have a good day! — Thanks, you too.`,`Хорошего дня! — Спасибо, и вам.`]],mistake:`Глагол — have, а не make. Вечером уместнее Have a good evening!`},{id:`see-you-tomorrow`,level:`A1`,topic:`Распорядок дня`,expression:`See you tomorrow!`,literal:`увижу тебя завтра!`,meaning:`прощание с тем, кого вы увидите на следующий день`,equivalent:`до завтра!`,register:`neutral`,examples:[[`Bye, Tom! See you tomorrow!`,`Пока, Том! До завтра!`],[`Good night, Kate! — Good night! See you tomorrow!`,`Спокойной ночи, Кейт! — Спокойной ночи! До завтра!`]],mistake:`Не Until tomorrow — так говорят редко, это звучит книжно. В обычной речи: See you tomorrow!`},{id:`sleep-well`,level:`A1`,topic:`Распорядок дня`,expression:`Sleep well!`,literal:`спи хорошо!`,meaning:`пожелание человеку, который ложится спать`,equivalent:`спи крепко! сладких снов!`,register:`neutral`,examples:[[`Good night, Anna. Sleep well!`,`Спокойной ночи, Анна. Спи крепко!`],[`It’s late. Sleep well! See you tomorrow!`,`Уже поздно. Сладких снов! До завтра!`]],mistake:`Не Sleep good: после глагола нужно наречие well, а не прилагательное good.`},{id:`what-do-you-do-for-fun`,level:`A1`,topic:`Хобби и свободное время`,expression:`What do you do for fun?`,literal:`что ты делаешь для веселья?`,meaning:`вопрос об увлечениях и о том, как человек отдыхает`,equivalent:`чем вы увлекаетесь? чем любите заниматься?`,register:`neutral`,examples:[[`What do you do for fun? — I play tennis and watch movies.`,`Чем вы любите заниматься? — Играю в теннис и смотрю фильмы.`]],mistake:`Не сокращайте до What do you do? — это вопрос о работе: «Кем вы работаете?».`},{id:`not-really`,level:`A1`,topic:`Хобби и свободное время`,expression:`Not really`,literal:`не реально`,meaning:`мягкий, вежливый ответ «нет» на вопрос о вкусах и привычках`,equivalent:`не особо, не очень`,register:`neutral`,examples:[[`Do you like soccer? — Not really.`,`Вам нравится футбол? — Не особо.`]],mistake:`Really здесь не значит «реально»: Not really — это смягчённое No.`},{id:`me-too`,level:`A1`,topic:`Хобби и свободное время`,expression:`Me too`,literal:`меня тоже`,meaning:`согласие с утверждением собеседника: у вас так же`,equivalent:`я тоже`,register:`neutral`,examples:[[`I love jazz. — Me too!`,`Я обожаю джаз. — Я тоже!`]],mistake:`Только после утверждения. После отрицания (I don’t…) говорят Me neither.`},{id:`me-neither`,level:`A1`,topic:`Хобби и свободное время`,expression:`Me neither`,literal:`меня ни то ни другое`,meaning:`согласие с отрицанием собеседника: вы тоже этого не делаете`,equivalent:`я тоже нет`,register:`neutral`,examples:[[`I don’t watch TV. — Me neither.`,`Я не смотрю телевизор. — Я тоже.`]],mistake:`На I don’t… по правилу отвечают Me neither, а не Me too. В американской разговорной речи встречается и Me either.`},{id:`as-usual`,level:`A1`,topic:`Привычки`,expression:`as usual`,literal:`как обычный`,meaning:`так же, как всегда бывает; часто с оттенком «опять»`,equivalent:`как обычно, как всегда`,register:`neutral`,examples:[[`Tom is late again, as usual.`,`Том опять опаздывает, как обычно.`]],mistake:`В выражении нет -ly: as usual, не as usually.`},{id:`from-time-to-time`,level:`A1`,topic:`Привычки`,expression:`from time to time`,literal:`от времени к времени`,meaning:`иногда, не регулярно`,equivalent:`время от времени`,register:`neutral`,examples:[[`I call my aunt from time to time.`,`Я время от времени звоню тёте.`]],mistake:`В отличие от sometimes, обычно стоит в конце или в начале предложения, а не перед глаголом. Time — без -s.`},{id:`not-very-often`,level:`A1`,topic:`Привычки`,expression:`Not very often`,literal:`не очень часто`,meaning:`короткий ответ на How often…?: редко, нечасто`,equivalent:`нечасто, не так уж часто`,register:`neutral`,examples:[[`How often do you go to the theater? — Not very often.`,`Как часто вы ходите в театр? — Нечасто.`]],mistake:`Перед наречием отрицание — not, а не no: не No very often.`},{id:`all-the-time`,level:`A1`,topic:`Привычки`,expression:`all the time`,literal:`всё то время`,meaning:`очень часто, постоянно; нередко с оттенком недовольства`,equivalent:`постоянно, всё время`,register:`neutral`,examples:[[`My little brother asks questions all the time.`,`Мой младший брат постоянно задаёт вопросы.`]],mistake:`Ставится в конце предложения, в отличие от always: He calls me all the time, но He always calls me.`},{id:`what-time-is-it`,level:`A1`,topic:`Время`,expression:`What time is it?`,literal:`какое время это есть?`,meaning:`вопрос о том, сколько сейчас на часах`,equivalent:`который час? / сколько времени?`,register:`neutral`,examples:[[`Excuse me, what time is it? — It’s half past six.`,`Извините, который час? — Половина седьмого.`]],mistake:`How much time is it? (калька «сколько времени») не говорят вообще: how much time спрашивает о количестве времени — How much time do we have? О часах — What time is it?`},{id:`see-you-on-monday`,level:`A1`,topic:`Время`,expression:`See you on Monday!`,literal:`увижу тебя в понедельник`,meaning:`прощание до встречи в определённый день`,equivalent:`до понедельника! / увидимся в понедельник!`,register:`neutral`,examples:[[`Bye, Anna! See you on Monday!`,`Пока, Анна! До понедельника!`],[`See you next week!`,`Увидимся на следующей неделе!`]],mistake:`С днём недели — on, не in: See you on Monday. В разговоре американцы часто опускают on: See you Monday! Перед next предлога нет: See you next week.`},{id:`have-a-nice-weekend`,level:`A1`,topic:`Время`,expression:`Have a nice weekend!`,literal:`имей хорошие выходные`,meaning:`пожелание при прощании в пятницу или перед выходными`,equivalent:`хороших выходных!`,register:`neutral`,examples:[[`Have a nice weekend! — Thanks, you too!`,`Хороших выходных! — Спасибо, и вам!`]],mistake:`Weekend — в единственном числе и с артиклем a: a nice weekend, не nice weekends. Так же часто говорят Have a good weekend! Ответ — Thanks, you too!`},{id:`im-late`,level:`A1`,topic:`Время`,expression:`I’m late!`,literal:`я поздний`,meaning:`я опаздываю или уже опоздал`,equivalent:`я опаздываю / я опоздал`,register:`neutral`,examples:[[`Sorry, I’m late! — That’s OK.`,`Простите, я опоздал! — Ничего страшного.`],[`I’m ten minutes late.`,`Я опаздываю на десять минут.`]],mistake:`Отдельного глагола «опаздывать» здесь нет — работает to be: I’m late. Время опоздания — перед late и без for: I’m ten minutes late, не I’m late for ten minutes. Куда опаздываете — через for: I’m late for work (в американском разговорном можно и late to work).`},{id:`can-i-help-you`,level:`A1`,topic:`Умения и просьбы`,expression:`Can I help you?`,literal:`Могу я помочь вам?`,meaning:`предложение помощи, например в магазине или кафе`,equivalent:`Вам помочь? Чем могу помочь?`,register:`neutral`,examples:[[`Hello! Can I help you?`,`Здравствуйте! Вам помочь?`],[`You look lost. Can I help you?`,`Вы, кажется, заблудились. Вам помочь?`]],mistake:`Не путайте роли: Can I help you? — предлагаете помощь вы. Если просите её сами, говорите Can you help me?`},{id:`no-problem`,level:`A1`,topic:`Умения и просьбы`,expression:`No problem.`,literal:`Нет проблемы.`,meaning:`вежливый ответ на «спасибо» или на просьбу, когда это нетрудно`,equivalent:`Не за что. Без проблем.`,register:`informal`,examples:[[`— Thanks for your help. — No problem.`,`— Спасибо за помощь. — Не за что.`],[`— Can you open the window? — No problem.`,`— Откроешь окно? — Без проблем.`]],mistake:`Это не «нет проблемы» в прямом смысле: фраза значит «пожалуйста, мне это нетрудно».`},{id:`go-ahead`,level:`A1`,topic:`Умения и просьбы`,expression:`Go ahead.`,literal:`Иди вперёд.`,meaning:`разрешение сделать то, о чём вас спросили`,equivalent:`Конечно, можно. Пожалуйста, действуйте.`,register:`neutral`,examples:[[`— Can I sit here? — Go ahead.`,`— Можно здесь сесть? — Конечно, садитесь.`],[`— Can I use your pen? — Sure, go ahead.`,`— Можно воспользоваться вашей ручкой? — Конечно, пожалуйста.`]],mistake:`Это не приказ «иди вперёд», а вежливое разрешение в ответ на Can I … ?`},{id:`can-you-say-that-again`,level:`A1`,topic:`Умения и просьбы`,expression:`Can you say that again?`,literal:`Можешь сказать это снова?`,meaning:`вежливая просьба повторить то, что вы не расслышали или не поняли`,equivalent:`Повторите, пожалуйста.`,register:`neutral`,examples:[[`Sorry, can you say that again?`,`Извините, повторите, пожалуйста.`],[`Can you say that again, please? Slowly.`,`Повторите, пожалуйста. Медленно.`]],mistake:`Не «Can you repeat again?»: repeat уже значит «повторить», again лишнее.`},{id:`have-fun`,level:`A1`,topic:`Пожелания`,expression:`Have fun!`,literal:`имей веселье!`,meaning:`пожелание хорошо провести время`,equivalent:`веселитесь! хорошо вам повеселиться!`,register:`informal`,examples:[[`We have a party tonight. — Have fun!`,`У нас сегодня вечеринка. — Веселитесь!`],[`I always have fun with my friends.`,`Мне всегда весело с друзьями.`]],mistake:`Без артикля: Have fun, а не Have a fun. В сочетании с have не нужен и got.`},{id:`i-have-no-idea`,level:`A1`,topic:`Разговор`,expression:`I have no idea`,literal:`у меня нет идеи`,meaning:`я совсем не знаю ответа`,equivalent:`понятия не имею`,register:`neutral`,examples:[[`Where is Tom? — I have no idea.`,`Где Том? — Понятия не имею.`],[`I have no idea. Ask Anna.`,`Понятия не имею. Спросите Анну.`]],mistake:`Перед существительным отрицание — слово no: I have no idea. Не «I haven’t idea» и не «I have not idea».`},{id:`i-have-to-go`,level:`A1`,topic:`Прощание`,expression:`I have to go`,literal:`я имею идти`,meaning:`вежливо сообщить, что вам пора уходить`,equivalent:`мне пора идти, мне надо идти`,register:`neutral`,examples:[[`Sorry, I have to go. See you tomorrow!`,`Извините, мне пора. До завтра!`],[`I have to go now. My bus is here.`,`Мне пора идти. Мой автобус подходит.`]],mistake:`Между have и go нужно to: I have to go, а не I have go.`},{id:`do-you-have-the-time`,level:`A1`,topic:`Время`,expression:`Do you have the time?`,literal:`у вас есть то самое время?`,meaning:`вежливый вопрос о том, который час`,equivalent:`не подскажете, который час?`,register:`neutral`,examples:[[`Excuse me, do you have the time? — It’s five o’clock.`,`Извините, не подскажете, который час? — Пять часов.`]],mistake:`С артиклем the это вопрос о времени на часах. Do you have time? без артикля — «у вас есть свободное время?».`},{id:`would-you-like-some`,level:`A1`,topic:`Еда и напитки`,expression:`Would you like some…?`,literal:`ты бы хотел немного…?`,meaning:`вежливое предложение угостить или предложить что-то`,equivalent:`хотите…? / не желаете…?`,register:`neutral`,examples:[[`Would you like some tea? — Yes, please.`,`Хотите чаю? — Да, пожалуйста.`],[`Would you like some more rice?`,`Хотите ещё риса?`]],mistake:`В предложении угостить ставят some, а не any: Would you like some tea?`},{id:`can-i-have`,level:`A1`,topic:`Еда и напитки`,expression:`Can I have…, please?`,literal:`могу я иметь…, пожалуйста?`,meaning:`вежливая просьба дать что-то в кафе, магазине или за столом`,equivalent:`можно мне…? / дайте, пожалуйста…`,register:`neutral`,examples:[[`Can I have some water, please?`,`Можно мне воды, пожалуйста?`],[`Can I have a sandwich, please?`,`Можно мне бутерброд, пожалуйста?`]],mistake:`Не Give me …: так звучит как приказ. Вежливо — Can I have …, please?`},{id:`id-like`,level:`A1`,topic:`Еда и напитки`,expression:`I’d like…`,literal:`я бы хотел…`,meaning:`вежливый способ заказать или попросить что-то`,equivalent:`я бы хотел… / мне, пожалуйста…`,register:`neutral`,examples:[[`I’d like some apple juice, please.`,`Мне, пожалуйста, яблочный сок.`],[`I’d like a table for two.`,`Я бы хотел столик на двоих.`]],mistake:`I want … звучит резко. В кафе вежливее I’d like …`},{id:`anything-else`,level:`A1`,topic:`Еда и напитки`,expression:`Anything else?`,literal:`что-нибудь другое?`,meaning:`вопрос продавца или официанта, нужно ли что-то ещё`,equivalent:`что-нибудь ещё?`,register:`neutral`,examples:[[`A sandwich and some juice. — Anything else? — No, that’s all.`,`Бутерброд и сок. — Что-нибудь ещё? — Нет, это всё.`]],mistake:`На Anything else? отвечают No, thanks или That’s all, а не Yes, I am: это не вопрос про состояние.`},{id:`ill-take-it`,level:`A1`,topic:`Магазин и кафе`,expression:`I’ll take it`,literal:`я возьму это`,meaning:`сообщить продавцу, что вы решили купить вещь`,equivalent:`беру`,register:`neutral`,examples:[[`How much are these shoes? — $40. — OK, I’ll take them.`,`Сколько стоят эти туфли? — 40 долларов. — Хорошо, беру.`],[`How much is it? — $5. — OK, I’ll take it.`,`Сколько стоит? — 5 долларов. — Хорошо, беру.`]],mistake:`Не говорите I buy it — это просто факт, а не решение «беру». О нескольких вещах: I’ll take them.`},{id:`can-i-pay-by-card`,level:`A1`,topic:`Магазин и кафе`,expression:`Can I pay by card?`,literal:`могу я заплатить картой?`,meaning:`спросить, принимают ли в магазине или кафе оплату картой`,equivalent:`можно картой?`,register:`neutral`,examples:[[`Can I pay by card? — Yes, of course.`,`Можно картой? — Да, конечно.`]],mistake:`Предлог by без артикля: by card, а не by the card. Наличными — in cash.`},{id:`thats-all`,level:`A1`,topic:`Магазин и кафе`,expression:`That’s all`,literal:`это всё`,meaning:`сказать, что вам больше ничего не нужно`,equivalent:`это всё, спасибо`,register:`neutral`,examples:[[`Anything else? — No, that’s all, thanks.`,`Что-нибудь ещё? — Нет, это всё, спасибо.`]],mistake:`В ответ на Anything else? привычнее That’s all или That’s it, чем дословное That is everything.`},{id:`keep-the-change`,level:`A1`,topic:`Магазин и кафе`,expression:`Keep the change`,literal:`оставьте сдачу`,meaning:`сказать, что сдачу возвращать не нужно`,equivalent:`сдачи не надо`,register:`neutral`,examples:[[`Here’s $10. Keep the change.`,`Вот 10 долларов. Сдачи не надо.`]],mistake:`Change здесь — «сдача», а не «изменение». Не путайте: Keep the change — это не «сохраните изменение».`},{id:`go-straight-ahead`,level:`A1`,topic:`Город и дорога`,expression:`Go straight ahead`,literal:`иди прямо вперёд`,meaning:`идти по дороге, никуда не сворачивая`,equivalent:`идите прямо`,register:`neutral`,examples:[[`Go straight ahead for two blocks. The bank is on the left.`,`Идите прямо два квартала. Банк будет слева.`],[`Go straight ahead, then turn right.`,`Идите прямо, потом поверните направо.`]],mistake:`Прямо — straight. Go right значит «идите направо», а не «прямо».`},{id:`on-the-corner`,level:`A1`,topic:`Город и дорога`,expression:`on the corner`,literal:`на углу`,meaning:`на углу улицы, там, где пересекаются две улицы`,equivalent:`на углу`,register:`neutral`,examples:[[`The café is on the corner.`,`Кафе находится на углу.`],[`Wait for me on the corner.`,`Подождите меня на углу.`]],mistake:`In the corner — это угол внутри комнаты или коробки. Угол улицы — on the corner.`},{id:`its-next-to`,level:`A1`,topic:`Город и дорога`,expression:`It’s next to…`,literal:`это следующее к…`,meaning:`находится рядом, вплотную к чему-то`,equivalent:`это рядом с…, это возле…`,register:`neutral`,examples:[[`The bus stop is next to the bank.`,`Остановка рядом с банком.`],[`It’s next to the supermarket.`,`Это рядом с супермаркетом.`]],mistake:`После next нужен to: next to the bank. Next the bank и next of the bank — ошибки.`},{id:`you-cant-miss-it`,level:`A1`,topic:`Город и дорога`,expression:`You can’t miss it`,literal:`вы не можете это пропустить`,meaning:`место очень заметное, вы его обязательно увидите`,equivalent:`не пропустите, сразу увидите`,register:`neutral`,examples:[[`Turn left at the corner. The hotel is big. You can’t miss it.`,`На углу поверните налево. Отель большой. Вы его не пропустите.`],[`It’s the red building. You can’t miss it.`,`Это красное здание. Вы его не пропустите.`]],mistake:`Это не угроза и не запрет: фраза успокаивает — найти место легко.`},{id:`whats-the-weather-like`,level:`A1`,topic:`Погода`,expression:`What’s the weather like?`,literal:`какая погода как?`,meaning:`вопрос о погоде за окном или в другом городе`,equivalent:`какая сейчас погода?`,register:`neutral`,examples:[[`What’s the weather like in Boston? — It’s cold and windy.`,`Какая погода в Бостоне? — Холодно и ветрено.`]],mistake:`Здесь like — предлог, а не глагол «нравиться»: What’s the weather like? — это «Какая погода?». Do you like the weather? — совсем другой вопрос: «Вам нравится погода?»`},{id:`what-are-you-doing`,level:`A1`,topic:`Общение`,expression:`What are you doing?`,literal:`что ты делаешь?`,meaning:`спросить, чем человек занят прямо сейчас`,equivalent:`чем занимаешься?`,register:`neutral`,examples:[[`Hi Sam! What are you doing? — I’m watching a movie.`,`Привет, Сэм! Чем занимаешься? — Смотрю фильм.`]],mistake:`Отвечайте тоже в Present Continuous: I’m watching TV, а не I watch TV.`},{id:`im-just-looking`,level:`A1`,topic:`Магазин`,expression:`I’m just looking`,literal:`я только смотрю`,meaning:`вежливо сказать продавцу, что вам пока ничего не нужно`,equivalent:`я пока просто смотрю, спасибо`,register:`neutral`,examples:[[`Can I help you? — No, thanks. I’m just looking.`,`Вам помочь? — Нет, спасибо. Я просто смотрю.`]],mistake:`Нужен Present Continuous: I’m just looking. Фраза I just look звучит как привычка. Just здесь значит «просто, только», а не «только что».`},{id:`that-looks-good-on-you`,level:`A1`,topic:`Одежда`,expression:`That looks good on you`,literal:`это хорошо выглядит на тебе`,meaning:`сделать комплимент: вещь вам подходит`,equivalent:`тебе идёт`,register:`neutral`,examples:[[`Do you like my new jacket? — Yes, it looks good on you!`,`Тебе нравится моя новая куртка? — Да, тебе очень идёт!`]],mistake:`«Тебе идёт» нельзя переводить как It goes to you. По-английски говорят That looks good on you.`},{id:`what-do-you-do`,level:`A1`,topic:`Работа и учёба`,expression:`What do you do?`,literal:`Что ты делаешь?`,meaning:`вопрос о профессии или основном занятии, а не о том, что человек делает в эту минуту`,equivalent:`Кем вы работаете? Чем занимаетесь?`,register:`neutral`,examples:[[`What do you do? — I’m a teacher.`,`Кем вы работаете? — Я учитель.`],[`What do you do? — I’m a student.`,`Чем вы занимаетесь? — Я студент.`]],mistake:`Не путайте с What are you doing? — так спрашивают о том, что человек делает прямо сейчас.`},{id:`what-are-you-up-to`,level:`A1`,topic:`Работа и учёба`,expression:`What are you up to?`,literal:`что ты вверху до?`,meaning:`неформальный вопрос о том, чем человек занимается сейчас`,equivalent:`Чем занимаешься?`,register:`informal`,examples:[[`Hi, Sam! What are you up to? — I’m cooking dinner.`,`Привет, Сэм! Чем занимаешься? — Готовлю ужин.`],[`What are you up to? — Nothing much. I’m watching TV.`,`Чем занимаешься? — Ничего особенного. Смотрю телевизор.`]],mistake:`Не говорите What do you up to? — после are нужна форма to be. И помните: это фраза для друзей; с начальством лучше сказать What are you doing?`},{id:`im-in-a-meeting`,level:`A1`,topic:`Работа и учёба`,expression:`I’m in a meeting.`,literal:`Я во встрече.`,meaning:`сейчас идёт совещание, поэтому разговаривать нельзя`,equivalent:`Я на совещании.`,register:`neutral`,examples:[[`Sorry, I’m in a meeting right now.`,`Извините, я сейчас на совещании.`],[`My boss is in a meeting.`,`Мой начальник на совещании.`]],mistake:`По-русски «на совещании», а по-английски in a meeting, не on.`},{id:`im-on-my-way`,level:`A1`,topic:`Работа и учёба`,expression:`I’m on my way.`,literal:`Я на моём пути.`,meaning:`я уже вышел и скоро буду на месте`,equivalent:`Уже иду. Уже еду.`,register:`neutral`,examples:[[`I’m on my way!`,`Уже иду!`],[`Wait for me. I’m on my way to the office.`,`Подождите меня. Я уже еду в офис.`]],mistake:`Не «I am in my way»: нужен предлог on.`},{id:`how-was-your-day`,level:`A1`,topic:`Разговор о прошлом`,expression:`How was your day?`,literal:`как был твой день?`,meaning:`вопрос о том, как прошёл день или какие были впечатления`,equivalent:`как прошёл твой день?`,register:`neutral`,examples:[[`Hi, Mom! — Hi, honey. How was your day?`,`Привет, мама! — Привет, дорогой. Как прошёл твой день?`],[`How was your day? — Not bad, just busy.`,`Как прошёл день? — Неплохо, просто занят.`]],mistake:`Day в единственном числе, поэтому How was your day?, а не How were your day?`},{id:`it-was-great`,level:`A1`,topic:`Впечатления`,expression:`It was great!`,literal:`это было великолепно!`,meaning:`эмоциональная оценка прошедшего события: поездки, вечера, фильма`,equivalent:`было здорово!`,register:`neutral`,examples:[[`How was the beach? — It was great!`,`Как на пляже? — Было здорово!`]],mistake:`Не пропускайте was: It was great!, а не It great!`},{id:`long-time-ago`,level:`A1`,topic:`Время`,expression:`a long time ago`,literal:`долгое время назад`,meaning:`о событии, которое случилось очень давно`,equivalent:`очень давно`,register:`neutral`,examples:[[`My grandfather was a child a long time ago.`,`Мой дедушка был ребёнком очень давно.`]],mistake:`Ago стоит после слов о времени: a long time ago, а не ago a long time.`},{id:`where-were-you-born`,level:`A1`,topic:`Знакомство`,expression:`Where were you born?`,literal:`где ты был рождён?`,meaning:`вопрос о месте рождения человека`,equivalent:`где ты родился?`,register:`neutral`,examples:[[`Where were you born? — I was born in Kazan.`,`Где ты родился? — Я родился в Казани.`]],mistake:`Не Where did you born? и не Where you were born?: was / were born — одно целое, а вопрос строится перестановкой: Where were you born?`},{id:`how-was-your-weekend`,level:`A1`,topic:`Выходные`,expression:`How was your weekend?`,literal:`Как был ваш выходной?`,meaning:`вопрос о том, как человек провёл выходные; задают в понедельник`,equivalent:`Как провёл выходные?`,register:`neutral`,examples:[[`Hi, Anna! How was your weekend?`,`Привет, Анна! Как провела выходные?`],[`How was your weekend? — Great, thanks!`,`Как выходные? — Отлично, спасибо!`]],mistake:`О выходных, которые уже прошли, говорят was, а не is: How was your weekend?`},{id:`what-did-you-do-last-weekend`,level:`A1`,topic:`Выходные`,expression:`What did you do last weekend?`,literal:`Что ты сделал прошлый выходной?`,meaning:`вопрос о том, чем человек занимался в прошлые выходные`,equivalent:`Чем занимался в выходные?`,register:`neutral`,examples:[[`What did you do last weekend? — I visited my parents.`,`Чем занимался в выходные? — Навещал родителей.`],[`What did you do last weekend? — We cleaned the house.`,`Что делали на выходных? — Убирались дома.`]],mistake:`После did глагол стоит в начальной форме (did you do, не did you did). Перед last предлога нет: last weekend, не in last weekend.`},{id:`nothing-special`,level:`A1`,topic:`Выходные`,expression:`Nothing special.`,literal:`Ничего специального.`,meaning:`ответ, когда ничего интересного не происходило`,equivalent:`Да так, ничего такого.`,register:`informal`,examples:[[`What did you do on Sunday? — Nothing special. I relaxed at home.`,`Что делал в воскресенье? — Да ничего особенного. Отдыхал дома.`],[`Nothing special. We just walked in the park.`,`Ничего особенного. Мы просто гуляли в парке.`]],mistake:`Прилагательное special стоит после nothing: nothing special, а не special nothing.`},{id:`sounds-great`,level:`A1`,topic:`Выходные`,expression:`Sounds great!`,literal:`Звучит здорово!`,meaning:`реакция на предложение или план: звучит хорошо`,equivalent:`Здорово! Классно!`,register:`informal`,examples:[[`Let’s have dinner at seven. — Sounds great!`,`Давай поужинаем в семь. — Здорово!`],[`We can walk in the park on Saturday. — Sounds great!`,`В субботу можно погулять в парке. — Здорово!`]],mistake:`Нужно Sounds great! с -s: это сокращение от That sounds great. Не говорите Sound great! или It great!`}],"../../../content/phrases/A2.ts":[{id:`get-up`,level:`A2`,topic:`Повседневные дела`,expression:`get up`,literal:`получить вверх`,meaning:`встать с постели утром`,equivalent:`вставать`,register:`neutral`,examples:[[`I get up at seven on weekdays.`,`По будням я встаю в семь.`],[`It’s Sunday — you don’t have to get up early.`,`Сегодня воскресенье — можно не вставать рано.`]],mistake:`Не путайте с wake up: wake up — проснуться, get up — встать с кровати. Можно проснуться в семь, а встать в восемь.`},{id:`look-for`,level:`A2`,topic:`Повседневные дела`,expression:`look for`,literal:`смотреть для`,meaning:`пытаться найти что-то или кого-то`,equivalent:`искать`,register:`neutral`,examples:[[`I’m looking for my keys. Have you seen them?`,`Я ищу ключи. Ты их не видел?`],[`She’s looking for a new job.`,`Она ищет новую работу.`]],mistake:`Предлог for обязателен: без него look значит «смотреть». Не search my keys — search the bag значит «обыскать сумку».`},{id:`look-after`,level:`A2`,topic:`Повседневные дела`,expression:`look after`,literal:`смотреть после`,meaning:`заботиться о ком-то или чём-то, присматривать`,equivalent:`присматривать за`,register:`neutral`,examples:[[`Can you look after my cat this weekend?`,`Можешь присмотреть за моей кошкой в эти выходные?`]],mistake:`Русское «за» не переводится отдельно: look after the kids, не look after of и не look behind. Look after звучит скорее по-британски; в американском английском чаще говорят take care of или watch: Can you watch my cat this weekend?`},{id:`turn-off`,level:`A2`,topic:`Повседневные дела`,expression:`turn off`,literal:`повернуть прочь`,meaning:`выключить свет, прибор, воду; противоположность — turn on`,equivalent:`выключить`,register:`neutral`,examples:[[`Please turn off the lights when you leave.`,`Пожалуйста, выключай свет, когда уходишь.`],[`Can you turn on the TV?`,`Можешь включить телевизор?`]],mistake:`Местоимение ставится между частями: turn it off, не turn off it. Пара: turn on — включить, turn off — выключить.`},{id:`be-in-a-hurry`,level:`A2`,topic:`Повседневные дела`,expression:`be in a hurry`,literal:`быть в спешке`,meaning:`торопиться, иметь мало времени`,equivalent:`спешить, торопиться`,register:`neutral`,examples:[[`Sorry, I can’t talk now — I’m in a hurry.`,`Извини, не могу сейчас говорить — я тороплюсь.`]],mistake:`Артикль a обязателен: I’m in a hurry, не I’m in hurry.`},{id:`make-a-mistake`,level:`A2`,topic:`Make, take, have`,expression:`make a mistake`,literal:`изготовить ошибку`,meaning:`ошибиться, сделать что-то неправильно`,equivalent:`ошибиться, допустить ошибку`,register:`neutral`,examples:[[`Everyone makes mistakes when they learn a language.`,`Все ошибаются, когда учат язык.`],[`Sorry, I made a mistake with your name.`,`Простите, я ошибся в вашем имени.`]],mistake:`Русское «делать ошибку» тянет к do, но с mistake всегда make: make a mistake, не do a mistake.`},{id:`take-a-photo`,level:`A2`,topic:`Make, take, have`,expression:`take a photo`,literal:`взять фото`,meaning:`сфотографировать`,equivalent:`сфотографировать, сделать снимок`,register:`neutral`,examples:[[`Could you take a photo of us, please?`,`Не могли бы вы нас сфотографировать?`],[`We took a lot of photos in Rome.`,`Мы сделали в Риме много фотографий.`]],mistake:`Не make a photo — это калька с «сделать фото». Фотографию «берут»: take a photo (или take a picture).`},{id:`have-a-good-time`,level:`A2`,topic:`Make, take, have`,expression:`have a good time`,literal:`иметь хорошее время`,meaning:`получить удовольствие от поездки, праздника, встречи`,equivalent:`хорошо провести время`,register:`neutral`,examples:[[`We had a great time at the party.`,`Мы отлично провели время на вечеринке.`],[`Have a good time in Paris!`,`Хорошо вам отдохнуть в Париже!`]],mistake:`Не spend a good time: spend time — «тратить время» (spend two hours), а «хорошо провести время» — have a good time.`},{id:`take-a-break`,level:`A2`,topic:`Make, take, have`,expression:`take a break`,literal:`взять перерыв`,meaning:`ненадолго остановиться, чтобы отдохнуть`,equivalent:`сделать перерыв, передохнуть`,register:`neutral`,examples:[[`We’ve worked for three hours. Let’s take a break.`,`Мы работаем уже три часа. Давай сделаем перерыв.`]],mistake:`Не make a break: с перерывом используется take — take a break, take a short break.`},{id:`never-mind`,level:`A2`,topic:`Реакции в разговоре`,expression:`Never mind`,literal:`никогда не возражай`,meaning:`ничего страшного; не важно, забудьте — когда успокаивают собеседника или отменяют свою просьбу`,equivalent:`ничего страшного; не важно`,register:`neutral`,examples:[[`Sorry, I forgot to buy milk. — Never mind, I’ll get some tomorrow.`,`Прости, я забыл купить молоко. — Ничего страшного, куплю завтра.`],[`What did you say? — Oh, never mind. It’s not important.`,`Что ты сказал? — А, забудь. Это неважно.`]],mistake:`Never mind не отвечают на thank you — для этого есть you’re welcome. И не Don’t mind: в этом значении фраза неизменна.`},{id:`what-a-pity`,level:`A2`,topic:`Реакции в разговоре`,expression:`What a pity!`,literal:`что за жалость!`,meaning:`реакция на неприятную новость: выражение сожаления`,equivalent:`как жаль!`,register:`neutral`,examples:[[`I can’t come to your party. — Oh, what a pity!`,`Я не смогу прийти на твою вечеринку. — Ой, как жаль!`]],mistake:`Артикль a обязателен: What a pity!, не What pity! и не How pity! В американском разговорном чаще говорят That’s too bad.`},{id:`i-cant-wait`,level:`A2`,topic:`Реакции в разговоре`,expression:`I can’t wait`,literal:`я не могу ждать`,meaning:`очень жду чего-то приятного, с нетерпением`,equivalent:`жду не дождусь`,register:`neutral`,examples:[[`We’re going to Spain next week. I can’t wait!`,`На следующей неделе мы едем в Испанию. Жду не дождусь!`],[`I can’t wait to see you.`,`Мне не терпится тебя увидеть.`]],mistake:`Это не жалоба на ожидание, а радостное нетерпение. Дальше — for + существительное (I can’t wait for the weekend) или to + глагол (I can’t wait to see you).`},{id:`hold-on`,level:`A2`,topic:`Реакции в разговоре`,expression:`Hold on`,literal:`держись`,meaning:`просьба немного подождать, в том числе по телефону`,equivalent:`подожди секунду, минутку`,register:`informal`,examples:[[`Hold on, I’ll get my keys.`,`Подожди секунду, я возьму ключи.`],[`Can I speak to Mr. Brown? — Hold on a second, please.`,`Можно поговорить с мистером Брауном? — Минутку, пожалуйста.`]],mistake:`В разговоре Hold on почти всегда значит «подождите», а не «держитесь». Поддержать человека в беде — Hang in there.`},{id:`its-up-to-you`,level:`A2`,topic:`Мнение и выбор`,expression:`It’s up to you`,literal:`это вверх до тебя`,meaning:`решать вам; мне подходит любой вариант`,equivalent:`как хочешь; решай сам`,register:`neutral`,examples:[[`Pizza or sushi? — I don’t mind. It’s up to you.`,`Пиццу или суши? — Мне всё равно. Решай сам.`]],mistake:`Предлог — up to: It’s up to you, не It’s up for you и не It’s on you (это «ты угощаешь»).`},{id:`it-depends`,level:`A2`,topic:`Мнение и выбор`,expression:`It depends`,literal:`это зависит`,meaning:`ответ зависит от обстоятельств`,equivalent:`смотря как; когда как`,register:`neutral`,examples:[[`Do you walk to work? — It depends on the weather.`,`Ты ходишь на работу пешком? — Смотря какая погода.`],[`Is it expensive? — It depends.`,`Это дорого? — Когда как.`]],mistake:`После depends — предлог on: It depends on the weather. Не depends of и не depends from — это калька с «зависит от».`},{id:`i-dont-mind`,level:`A2`,topic:`Мнение и выбор`,expression:`I don’t mind`,literal:`я не возражаю`,meaning:`мне подходит любой вариант; я не против`,equivalent:`мне всё равно; я не против`,register:`neutral`,examples:[[`Tea or coffee? — I don’t mind.`,`Чай или кофе? — Мне всё равно.`],[`Do you mind if I open the window? — No, I don’t mind.`,`Вы не против, если я открою окно? — Нет, не против.`]],mistake:`На вопрос Do you mind…? согласие — No (I don’t mind). Ответ Yes значит «да, я против» — частая ловушка для русскоязычных.`},{id:`how-was-your-trip`,level:`A2`,topic:`Путешествия`,expression:`How was your trip?`,literal:`как была твоя поездка`,meaning:`вопрос человеку, который вернулся из поездки или путешествия`,equivalent:`Как съездили?`,register:`neutral`,examples:[[`Hi, Anna! How was your trip?`,`Привет, Анна! Как съездила?`],[`How was your trip to Spain?`,`Как прошла поездка в Испанию?`]],mistake:`Если человек уже вернулся, спрашивайте в прошедшем времени: How was your trip? Форма How is your trip? подойдёт, только пока он ещё в пути.`},{id:`get-back-from`,level:`A2`,topic:`Путешествия`,expression:`get back from`,literal:`получить назад от`,meaning:`вернуться откуда-то, например из отпуска или поездки`,equivalent:`вернуться из`,register:`neutral`,examples:[[`We got back from Italy on Sunday.`,`Мы вернулись из Италии в воскресенье.`],[`When did you get back from your trip?`,`Когда вы вернулись из поездки?`]],mistake:`Не путайте предлоги: get back from Italy — вернуться из Италии, get back to Italy — вернуться в Италию, get back to work — вернуться к работе.`},{id:`miss-a-flight`,level:`A2`,topic:`Путешествия`,expression:`miss a flight`,literal:`скучать по рейсу`,meaning:`опоздать на самолёт и не улететь`,equivalent:`опоздать на рейс`,register:`neutral`,examples:[[`We missed our flight because of the traffic.`,`Мы опоздали на рейс из-за пробок.`],[`Hurry up, or we will miss the flight!`,`Поторопитесь, а то мы опоздаем на рейс!`]],mistake:`Miss здесь значит «упустить», а не «скучать»: we missed the flight — рейс улетел без нас. Так же: miss the bus, miss the train.`},{id:`it-was-worth-it`,level:`A2`,topic:`Путешествия`,expression:`It was worth it.`,literal:`это было достойно этого`,meaning:`потраченные время, деньги или усилия оправдались`,equivalent:`Оно того стоило.`,register:`neutral`,examples:[[`The trip was long, but it was worth it.`,`Поездка была долгой, но оно того стоило.`],[`The tickets were expensive, but it was worth it.`,`Билеты были дорогие, но оно того стоило.`]],mistake:`Нужен именно worth, а не worthy: It was worth it.`},{id:`what-happened`,level:`A2`,topic:`Истории и события`,expression:`What happened?`,literal:`что произошло`,meaning:`вопрос о том, что произошло: когда видите, что что-то не так, или хотите услышать историю`,equivalent:`Что случилось?`,register:`neutral`,examples:[[`You look upset. What happened?`,`У тебя расстроенный вид. Что случилось?`],[`What happened after the concert?`,`Что было после концерта?`]],mistake:`Did не нужен: what здесь подлежащее. Не What did happen?`},{id:`guess-what`,level:`A2`,topic:`Истории и события`,expression:`Guess what!`,literal:`угадай что`,meaning:`фраза, которой начинают рассказ о новости или интересном событии`,equivalent:`представляешь! / знаешь что?`,register:`informal`,examples:[[`Guess what! We got tickets to the concert.`,`Представляешь! Мы достали билеты на концерт.`],[`Guess what happened to me yesterday.`,`Представляешь, что со мной вчера случилось.`]],mistake:`Это не просьба угадывать, а способ привлечь внимание перед новостью.`},{id:`no-way`,level:`A2`,topic:`Истории и события`,expression:`No way!`,literal:`никакого пути`,meaning:`выражение удивления и недоверия в ответ на неожиданную новость`,equivalent:`не может быть!`,register:`informal`,examples:[[`— I met a famous actor today. — No way!`,`— Сегодня я встретил знаменитого актёра. — Не может быть!`],[`No way! You lost your passport again?`,`Не может быть! Ты опять потерял паспорт?`]],mistake:`No way! может значить и твёрдое «ни за что» (— Come with us. — No way!), поэтому смотрите на ситуацию.`},{id:`in-the-end`,level:`A2`,topic:`Истории и события`,expression:`in the end`,literal:`в конце`,meaning:`в итоге, после всех событий или раздумий; чем всё закончилось`,equivalent:`в конце концов`,register:`neutral`,examples:[[`We were lost for an hour, but in the end we found the hotel.`,`Мы час не могли найти дорогу, но в конце концов нашли отель.`],[`In the end, he didn’t go to the party.`,`В итоге он не пошёл на вечеринку.`]],mistake:`In the end — «в итоге», а at the end — «в конце чего-то» (at the end of the film).`},{id:`by-accident`,level:`A2`,topic:`Происшествия`,expression:`by accident`,literal:`по несчастному случаю`,meaning:`случайно, непреднамеренно`,equivalent:`нечаянно, случайно`,register:`neutral`,examples:[[`I deleted the photos by accident.`,`Я нечаянно удалил фотографии.`],[`I sent the message to the wrong person by accident.`,`Я нечаянно отправил сообщение не тому человеку.`]],mistake:`Артикля нет: by accident, а не by an accident. Противоположность — on purpose (нарочно).`},{id:`all-of-a-sudden`,level:`A2`,topic:`Происшествия`,expression:`all of a sudden`,literal:`всё из внезапного`,meaning:`неожиданно, в один момент`,equivalent:`вдруг, внезапно`,register:`neutral`,examples:[[`We were talking, and all of a sudden the lights went out.`,`Мы разговаривали, и вдруг погас свет.`],[`All of a sudden, it started to rain.`,`Вдруг пошёл дождь.`]],mistake:`Устойчивая форма: all of a sudden. Не говорите all of sudden и all of a suddenly.`},{id:`in-the-middle-of`,level:`A2`,topic:`Происшествия`,expression:`in the middle of`,literal:`в середине из`,meaning:`в самый разгар чего-то или посреди какого-то места`,equivalent:`посреди, в разгар`,register:`neutral`,examples:[[`I was in the middle of dinner when he called.`,`Я как раз ужинал, когда он позвонил.`],[`The car stopped in the middle of the road.`,`Машина остановилась посреди дороги.`]],mistake:`После of идёт существительное или глагол с -ing: in the middle of cooking, а не in the middle of cook.`},{id:`out-of-nowhere`,level:`A2`,topic:`Происшествия`,expression:`out of nowhere`,literal:`из нигде`,meaning:`о чём-то, что появилось совершенно неожиданно`,equivalent:`откуда ни возьмись`,register:`informal`,examples:[[`A dog jumped into the road out of nowhere, and I stopped.`,`Откуда ни возьмись на дорогу выскочила собака, и я остановился.`],[`The storm came out of nowhere.`,`Буря налетела внезапно.`]],mistake:`Артикля нет: out of nowhere, а не out of the nowhere. Предлог всегда out of, не from.`},{id:`when-i-was-a-kid`,level:`A2`,topic:`Детство`,expression:`when I was a kid`,literal:`когда я был козлёнком`,meaning:`в детстве, в то время, когда говорящий был ребёнком`,equivalent:`когда я был маленьким`,register:`informal`,examples:[[`When I was a kid, I wanted to be a pilot.`,`Когда я был маленьким, я хотел стать пилотом.`],[`We used to go fishing when I was a kid.`,`В детстве мы ходили на рыбалку.`]],mistake:`Kid здесь значит «ребёнок», а не «козлёнок». В речи «когда я был маленьким» чаще звучит как when I was a kid или when I was little; when I was a child чуть более нейтрально.`},{id:`grow-up`,level:`A2`,topic:`Детство`,expression:`grow up`,literal:`расти вверх`,meaning:`становиться взрослым, проводить детство где-то`,equivalent:`вырасти; провести детство (где-то)`,register:`neutral`,examples:[[`I grew up in a small town near Kazan.`,`Я вырос в маленьком городке под Казанью.`],[`What do you want to be when you grow up?`,`Кем ты хочешь стать, когда вырастешь?`]],mistake:`Без up глагол grow значит «расти» о растениях и вещах: The tree grows fast. О человеке, который стал взрослым, нужно grow up.`},{id:`back-in-the-day`,level:`A2`,topic:`Детство`,expression:`back in the day`,literal:`назад в тот день`,meaning:`в прошлые времена, когда всё было иначе`,equivalent:`в своё время, в старые добрые времена`,register:`informal`,examples:[[`Back in the day, we used to write letters.`,`В своё время мы писали друг другу письма.`],[`Back in the day, this street was full of small shops.`,`Раньше эта улица была полна маленьких магазинов.`]],mistake:`Это идиома: day здесь значит «времена», а не «день». Говорят именно back in the day, с the. Выражение ставят в начале или в конце предложения: We wrote letters back in the day.`},{id:`those-were-the-days`,level:`A2`,topic:`Детство`,expression:`those were the days`,literal:`то были дни`,meaning:`так говорят, когда вспоминают приятное прошлое`,equivalent:`славные были времена`,register:`informal`,examples:[[`We played outside until dark. Those were the days!`,`Мы играли на улице до темноты. Славные были времена!`],[`No homework, no worries. Those were the days.`,`Ни уроков, ни забот. Хорошее было время.`]],mistake:`Выражение устойчивое, менять его части нельзя. Those were the days — «славные были времена», а those were days или that was the day значат совсем другое.`},{id:`take-after`,level:`A2`,topic:`Детство`,expression:`take after`,literal:`брать после`,meaning:`быть похожим на родителя или родственника характером или внешностью`,equivalent:`пойти в кого-то, быть похожим`,register:`neutral`,examples:[[`She takes after her mother: she is kind and funny.`,`Она в маму: добрая и весёлая.`],[`Who do you take after, your dad or your mom?`,`На кого ты похож, на папу или на маму?`]],mistake:`Take after говорят только о родственниках (обычно о родителях). О сходстве с другими людьми используйте look like (внешность) или be like (характер): He looks like my friend.`},{id:`do-your-best`,level:`A2`,topic:`Спорт и навыки`,expression:`do your best`,literal:`сделай своё лучшее`,meaning:`постараться изо всех сил`,equivalent:`сделать всё возможное, постараться`,register:`neutral`,examples:[[`Just do your best. That’s all I ask.`,`Просто постарайся. Это всё, о чём я прошу.`],[`We did our best, but we lost the game.`,`Мы сделали всё возможное, но проиграли матч.`]],mistake:`Глагол здесь do, а не make: do your best. Притяжательное слово меняется по лицу: do my best, do his best, do our best.`},{id:`keep-fit`,level:`A2`,topic:`Спорт и навыки`,expression:`keep fit`,literal:`держать подходящим`,meaning:`поддерживать хорошую физическую форму`,equivalent:`быть в форме, поддерживать форму`,register:`neutral`,examples:[[`I swim twice a week to keep fit.`,`Я плаваю два раза в неделю, чтобы быть в форме.`],[`My grandfather keeps fit by walking every day.`,`Мой дедушка поддерживает форму ежедневными прогулками.`]],mistake:`После keep здесь идёт прилагательное fit, а не наречие: keep fit, а не keep fitly.`},{id:`practice-makes-perfect`,level:`A2`,topic:`Спорт и навыки`,expression:`practice makes perfect`,literal:`практика делает совершенным`,meaning:`чем больше тренируешься, тем лучше получается`,equivalent:`повторенье — мать ученья`,register:`neutral`,examples:[[`Don’t give up. Practice makes perfect.`,`Не сдавайся. Повторенье — мать ученья.`],[`My piano teacher always says, “Practice makes perfect.”`,`Мой учитель музыки всегда говорит: «Повторенье — мать ученья».`]],mistake:`Пословица звучит именно так, без артикля и без изменений: practice makes perfect, а не the practice makes perfect.`},{id:`get-better-at`,level:`A2`,topic:`Спорт и навыки`,expression:`get better at`,literal:`становиться лучше в`,meaning:`улучшать умение или навык`,equivalent:`совершенствоваться в чём-то, делать что-то лучше`,register:`neutral`,examples:[[`I want to get better at tennis.`,`Я хочу играть в теннис лучше.`],[`She is getting better at drawing every month.`,`С каждым месяцем она рисует всё лучше.`]],mistake:`Предлог после better — at, а не in и не on: get better at English. После at глагол принимает форму -ing: get better at swimming.`},{id:`well-done`,level:`A2`,topic:`Спорт и навыки`,expression:`well done`,literal:`хорошо сделано`,meaning:`похвала за удачно выполненное дело`,equivalent:`молодец, отлично сработано`,register:`neutral`,examples:[[`You passed the test? Well done!`,`Ты сдал тест? Молодец!`],[`Well done, team! We won the match.`,`Молодцы, команда! Мы выиграли матч.`]],mistake:`Здесь well, а не good: well done — «хорошо сделано». Good job — похожая, но другая фраза.`},{id:`as-good-as-new`,level:`A2`,topic:`Покупки и размеры`,expression:`as good as new`,literal:`так же хорошо, как новый`,meaning:`вещь выглядит и работает как новая, хотя уже использовалась или была сломана`,equivalent:`как новый`,register:`neutral`,examples:[[`I bought this bike second-hand, but it’s as good as new.`,`Я купил этот велосипед с рук, но он как новый.`],[`The repair was cheap, and my phone is as good as new.`,`Ремонт был недорогой, и мой телефон как новый.`]],mistake:`Выражение целиком: as good as new. Нельзя сказать as good like new или good as a new.`},{id:`too-good-to-be-true`,level:`A2`,topic:`Покупки и размеры`,expression:`too good to be true`,literal:`слишком хорошо, чтобы быть правдой`,meaning:`так хорошо, что трудно поверить: возможно, это обман`,equivalent:`слишком хорошо, чтобы быть правдой`,register:`neutral`,examples:[[`A new laptop for $50? That’s too good to be true.`,`Новый ноутбук за 50 долларов? Это слишком хорошо, чтобы быть правдой.`],[`The offer sounds too good to be true.`,`Это предложение звучит слишком заманчиво, чтобы быть правдой.`]],mistake:`После too good идёт to be true, а не that it is true.`},{id:`enough-is-enough`,level:`A2`,topic:`Эмоции и реакции`,expression:`enough is enough`,literal:`достаточно есть достаточно`,meaning:`хватит, терпение закончилось, это пора прекратить`,equivalent:`хватит, довольно`,register:`informal`,examples:[[`You’ve been playing games for five hours. Enough is enough!`,`Ты играешь уже пять часов. Хватит!`],[`Enough is enough. I’m going to talk to the manager.`,`С меня хватит. Я поговорю с менеджером.`]],mistake:`Это устойчивая фраза: enough is enough. Не меняйте её на it is enough.`},{id:`as-far-as-i-know`,level:`A2`,topic:`Разговор`,expression:`as far as I know`,literal:`так далеко, как я знаю`,meaning:`насколько мне известно; говорящий не уверен на сто процентов`,equivalent:`насколько я знаю`,register:`neutral`,examples:[[`As far as I know, the shop closes at nine.`,`Насколько я знаю, магазин закрывается в девять.`],[`As far as I know, this size is out of stock.`,`Насколько мне известно, этого размера нет в наличии.`]],mistake:`Нужно as far as, а не how far I know. Глагол know остаётся в начальной форме.`},{id:`better-late-than-never`,level:`A2`,topic:`Пословицы и сравнения`,expression:`better late than never`,literal:`лучше поздно, чем никогда`,meaning:`лучше сделать что-то с опозданием, чем не сделать совсем`,equivalent:`лучше поздно, чем никогда`,register:`neutral`,examples:[[`I finally called my grandma. Better late than never.`,`Я наконец позвонил бабушке. Лучше поздно, чем никогда.`],[`You came an hour late, but better late than never.`,`Вы пришли на час позже, но лучше поздно, чем никогда.`]],mistake:`Слова не меняются и не добавляются: better late than never, а не it is better to be late than never.`},{id:`the-more-the-merrier`,level:`A2`,topic:`Пословицы и сравнения`,expression:`the more the merrier`,literal:`чем больше, тем веселее`,meaning:`чем больше людей, тем лучше и веселее`,equivalent:`чем больше народу, тем веселее`,register:`informal`,examples:[[`Can I bring a friend? — Sure, the more the merrier!`,`Можно привести друга? — Конечно, чем больше народу, тем веселее!`],[`We are having a party. The more the merrier.`,`Мы устраиваем вечеринку. Чем больше гостей, тем лучше.`]],mistake:`Артикль the стоит перед обеими частями: the more the merrier, а не more the merrier.`},{id:`better-safe-than-sorry`,level:`A2`,topic:`Пословицы и сравнения`,expression:`better safe than sorry`,literal:`лучше осторожным, чем сожалеющим`,meaning:`лучше принять меры заранее, чем потом жалеть`,equivalent:`лучше перестраховаться, чем потом жалеть`,register:`neutral`,examples:[[`Take an umbrella. Better safe than sorry.`,`Возьми зонт. Лучше перестраховаться.`],[`I checked the door twice. Better safe than sorry.`,`Я дважды проверил дверь. Лучше перестраховаться, чем потом жалеть.`]],mistake:`Это готовая формула: better safe than sorry. Заменять safe на careful не нужно.`},{id:`get-better`,level:`A2`,topic:`Здоровье и перемены`,expression:`get better`,literal:`получить лучше`,meaning:`становиться лучше: о здоровье, погоде или ситуации`,equivalent:`поправляться, улучшаться`,register:`neutral`,examples:[[`I hope you get better soon.`,`Надеюсь, вы скоро поправитесь.`],[`My English is getting better every month.`,`Мой английский становится лучше с каждым месяцем.`]],mistake:`После get ставится сравнительная форма без more: get better, get worse, а не get more good.`},{id:`more-or-less`,level:`A2`,topic:`Пословицы и сравнения`,expression:`more or less`,literal:`больше или меньше`,meaning:`примерно, в основном`,equivalent:`более или менее, плюс-минус`,register:`neutral`,examples:[[`The trip takes two hours, more or less.`,`Поездка занимает примерно два часа.`],[`Are you ready? — More or less.`,`Вы готовы? — Более или менее.`]],mistake:`Устойчивая форма — more or less, а не more and less.`},{id:`for-ages`,level:`A2`,topic:`Время и длительность`,expression:`for ages`,literal:`на века`,meaning:`очень долго, много времени`,equivalent:`целую вечность`,register:`informal`,examples:[[`I haven’t seen him for ages.`,`Я не видел его целую вечность.`],[`We have known each other for ages.`,`Мы знакомы целую вечность.`]],mistake:`Выражение стоит в Present Perfect: I have waited for ages, а не I wait for ages.`},{id:`ever-since`,level:`A2`,topic:`Время и длительность`,expression:`ever since`,literal:`всегда с тех пор`,meaning:`постоянно с какого-то момента до сегодняшнего дня`,equivalent:`с тех самых пор`,register:`neutral`,examples:[[`I moved here in 2019 and have lived here ever since.`,`Я переехал сюда в 2019 году и с тех пор живу здесь.`],[`She has loved music ever since she was a child.`,`Она любит музыку с самого детства.`]],mistake:`Ever since тоже требует Present Perfect: have lived ever since, а не live ever since.`},{id:`its-been-a-while`,level:`A2`,topic:`Время и длительность`,expression:`it’s been a while`,literal:`это было некоторое время`,meaning:`прошло много времени с последней встречи или события`,equivalent:`давненько`,register:`neutral`,examples:[[`Hi, Anna! It’s been a while.`,`Привет, Анна! Давненько не виделись.`],[`It’s been a while since I played tennis.`,`Давненько я не играл в теннис.`]],mistake:`Нужна форма Present Perfect: it’s been, а не it was a while.`},{id:`how-long-have-you-lived-here`,level:`A2`,topic:`Время и длительность`,expression:`How long have you lived here?`,literal:`Как долго вы жили здесь?`,meaning:`вопрос о том, как давно человек живёт в этом месте`,equivalent:`Давно вы здесь живёте?`,register:`neutral`,examples:[[`How long have you lived here?`,`Давно вы здесь живёте?`],[`How long have you worked here?`,`Как давно вы здесь работаете?`]],mistake:`Нужен Present Perfect, не How long do you live here и не How long time.`},{id:`so-far-so-good`,level:`A2`,topic:`Время и длительность`,expression:`so far so good`,literal:`пока что хорошо`,meaning:`до сих пор всё идёт хорошо`,equivalent:`пока всё хорошо`,register:`neutral`,examples:[[`How is your new job? — So far so good.`,`Как твоя новая работа? — Пока всё хорошо.`],[`We have been here for an hour, and so far so good.`,`Мы здесь уже час, и пока всё хорошо.`]],mistake:`Выражение неизменяемо: so far so good, без слова it или is.`},{id:`make-plans`,level:`A2`,topic:`Планы и цели`,expression:`make plans`,literal:`делать планы`,meaning:`договариваться о том, что вы будете делать в будущем`,equivalent:`строить планы, планировать`,register:`neutral`,examples:[[`Let’s make plans for the weekend.`,`Давайте распланируем выходные.`],[`I don’t want to make plans yet.`,`Я пока не хочу ничего планировать.`]],mistake:`Глагол здесь make, а не do: make plans.`},{id:`be-about-to`,level:`A2`,topic:`Планы и цели`,expression:`be about to`,literal:`быть около того, чтобы`,meaning:`вот-вот что-то сделать, находиться на грани действия`,equivalent:`вот-вот, уже собираться`,register:`neutral`,examples:[[`I’m about to leave. Can I call you back?`,`Я уже выхожу. Можно перезвоню?`],[`The movie is about to start.`,`Фильм вот-вот начнётся.`]],mistake:`После about to стоит начальная форма глагола, без -ing: about to leave.`},{id:`change-of-plans`,level:`A2`,topic:`Планы и цели`,expression:`change of plans`,literal:`изменение планов`,meaning:`ситуация, когда планы изменились`,equivalent:`планы поменялись`,register:`neutral`,examples:[[`Sorry, there’s been a change of plans.`,`Извини, планы поменялись.`],[`We have a change of plans: the party is on Sunday.`,`У нас изменились планы: вечеринка в воскресенье.`]],mistake:`Говорят a change of plans, а не a change of plan.`},{id:`im-thinking-of`,level:`A2`,topic:`Планы и цели`,expression:`I’m thinking of`,literal:`я думаю о`,meaning:`рассматривать возможность что-то сделать, ещё не решив окончательно`,equivalent:`подумываю, размышляю`,register:`neutral`,examples:[[`I’m thinking of changing my job.`,`Я подумываю сменить работу.`],[`She’s thinking of moving to Spain.`,`Она подумывает переехать в Испанию.`]],mistake:`После of идёт форма на -ing: thinking of going, а не thinking of go.`},{id:`fingers-crossed`,level:`A2`,topic:`Планы и цели`,expression:`fingers crossed`,literal:`пальцы скрещены`,meaning:`выражение надежды, что всё получится`,equivalent:`держу кулаки`,register:`informal`,examples:[[`I’ve got an interview tomorrow. Fingers crossed!`,`Завтра у меня собеседование. Держу кулаки!`],[`Fingers crossed it doesn’t rain.`,`Будем надеяться, что дождя не будет.`]],mistake:`Дословно «держать кулаки» не переводится: говорят fingers crossed (скрещенные пальцы).`},{id:`not-yet`,level:`A2`,topic:`Домашние дела`,expression:`Not yet.`,literal:`не ещё`,meaning:`краткий ответ на вопрос с yet: действие пока не выполнено`,equivalent:`ещё нет`,register:`neutral`,examples:[[`— Have you done the dishes? — Not yet.`,`— Ты помыл посуду? — Ещё нет.`],[`Not yet, but I will do it soon.`,`Ещё нет, но скоро сделаю.`]],mistake:`Не говорите No yet или Not already: устойчивый ответ — только Not yet.`},{id:`just-in-case`,level:`A2`,topic:`Домашние дела`,expression:`just in case`,literal:`просто в случае`,meaning:`на тот случай, если что-то понадобится или случится`,equivalent:`на всякий случай`,register:`neutral`,examples:[[`Take an umbrella just in case.`,`Возьми зонт на всякий случай.`],[`I made extra food just in case.`,`Я приготовил побольше еды на всякий случай.`]],mistake:`Нужно in case, а не in the case: just in case.`},{id:`ive-just-had-an-idea`,level:`A2`,topic:`Домашние дела`,expression:`I’ve just had an idea`,literal:`я только что имел идею`,meaning:`говорят, когда в голову только что пришла мысль`,equivalent:`мне только что пришла идея`,register:`neutral`,examples:[[`I’ve just had an idea: let’s cook together.`,`Мне пришла идея: давай приготовим вместе.`],[`I’ve just had an idea for the party.`,`Мне только что пришла идея для вечеринки.`]],mistake:`Идея «приходит», но по-английски её «имеют»: have an idea, а не come an idea.`},{id:`are-we-there-yet`,level:`A2`,topic:`Домашние дела`,expression:`Are we there yet?`,literal:`мы там ещё?`,meaning:`нетерпеливый вопрос о том, закончилась ли дорога или ожидание`,equivalent:`мы уже приехали?`,register:`informal`,examples:[[`Mom, are we there yet?`,`Мам, мы уже приехали?`],[`Are we there yet? I am so tired.`,`Мы уже приехали? Я так устал.`]]},{id:`follow-the-rules`,level:`A2`,topic:`Правила и работа`,expression:`follow the rules`,literal:`следовать правилам`,meaning:`делать то, что требуют правила`,equivalent:`соблюдать правила`,register:`neutral`,examples:[[`All drivers have to follow the rules.`,`Все водители должны соблюдать правила.`],[`Please follow the rules of the gym.`,`Пожалуйста, соблюдайте правила спортзала.`]],mistake:`По-русски «соблюдать», но по-английски follow, а не keep the rules.`},{id:`its-against-the-rules`,level:`A2`,topic:`Правила и работа`,expression:`it’s against the rules`,literal:`это против правил`,meaning:`правила этого не позволяют`,equivalent:`так нельзя, это запрещено`,register:`neutral`,examples:[[`You can’t eat here. It’s against the rules.`,`Здесь нельзя есть. Это запрещено правилами.`],[`Is it against the rules to use a phone?`,`Правила запрещают пользоваться телефоном?`]],mistake:`В английском нужно подлежащее it: it’s against the rules, а не просто against the rules.`},{id:`you-dont-have-to-worry`,level:`A2`,topic:`Правила и работа`,expression:`you don’t have to worry`,literal:`тебе не нужно беспокоиться`,meaning:`нет причин волноваться`,equivalent:`не переживай, не волнуйся`,register:`neutral`,examples:[[`You don’t have to worry. I’ll be there on time.`,`Не переживай. Я приду вовремя.`],[`You don’t have to worry about the deadline.`,`Насчёт срока можно не волноваться.`]],mistake:`You mustn’t worry звучит как запрет волноваться. Для успокоения нужно don’t have to.`},{id:`work-overtime`,level:`A2`,topic:`Правила и работа`,expression:`work overtime`,literal:`работать сверхурочно`,meaning:`работать больше обычного рабочего времени`,equivalent:`перерабатывать, задерживаться на работе`,register:`neutral`,examples:[[`I had to work overtime on Friday.`,`В пятницу мне пришлось задержаться на работе.`],[`Do you often work overtime?`,`Ты часто перерабатываешь?`]],mistake:`Overtime без предлога и артикля: work overtime, а не work in overtime.`},{id:`im-free-on`,level:`A2`,topic:`Встречи и расписание`,expression:`I’m free on…`,literal:`я свободный на…`,meaning:`сообщить, что у вас нет планов в это время и вы можете встретиться`,equivalent:`в … я свободен`,register:`neutral`,examples:[[`I’m free on Thursday afternoon.`,`В четверг после обеда я свободен.`],[`Do you want to meet? I’m free on Saturday.`,`Хочешь встретиться? В субботу я свободен.`]],mistake:`С днём недели нужен предлог on (on Thursday), с часом — at (at five). Слово free может значить и «бесплатный», смысл ясен из контекста.`},{id:`can-we-reschedule`,level:`A2`,topic:`Встречи и расписание`,expression:`Can we reschedule?`,literal:`можем ли мы пере-расписать?`,meaning:`вежливо попросить перенести встречу на другое время`,equivalent:`можем перенести?`,register:`neutral`,examples:[[`I’m sorry, I’m sick. Can we reschedule?`,`Простите, я заболел. Можем перенести встречу?`],[`Can we reschedule our call to Friday?`,`Можем перенести наш звонок на пятницу?`]],mistake:`Русское «перенести» не переводится словом transfer. Для встреч и звонков говорят reschedule.`},{id:`lets-meet-up`,level:`A2`,topic:`Встречи и расписание`,expression:`let’s meet up`,literal:`давайте встретимся вверх`,meaning:`неформально предложить увидеться`,equivalent:`давай увидимся`,register:`informal`,examples:[[`Let’s meet up on Saturday.`,`Давай увидимся в субботу.`],[`We should meet up for coffee soon.`,`Нам надо скоро встретиться за кофе.`]],mistake:`После let’s глагол стоит без to: let’s meet up, а не let’s to meet up.`},{id:`let-me-check-my-schedule`,level:`A2`,topic:`Встречи и расписание`,expression:`let me check my schedule`,literal:`позвольте мне проверить моё расписание`,meaning:`сказать, что вы посмотрите, свободны ли вы в это время`,equivalent:`сейчас гляну, что у меня по времени`,register:`neutral`,examples:[[`Let me check my schedule and call you back.`,`Посмотрю своё расписание и перезвоню вам.`],[`Let me check my schedule. I think I’m free at four.`,`Дайте гляну расписание. Кажется, в четыре я свободен.`]],mistake:`После let me глагол стоит без to: let me check, а не let me to check.`},{id:`been-there-done-that`,level:`A2`,topic:`Впечатления`,expression:`been there, done that`,literal:`был там, сделал это`,meaning:`я уже всё это пробовал, и мне это неинтересно или не в новинку`,equivalent:`проходили, знаем`,register:`informal`,examples:[[`Another day at the beach? Been there, done that.`,`Опять на пляж? Проходили, знаем.`],[`Skydiving? Been there, done that. I want something new.`,`Прыжки с парашютом? Проходили. Хочу чего-то нового.`]],mistake:`Фраза всегда в сокращённом виде, без have: been there, done that.`},{id:`once-in-a-lifetime`,level:`A2`,topic:`Впечатления`,expression:`once in a lifetime`,literal:`один раз за жизнь`,meaning:`бывает только один раз; редкая, уникальная возможность`,equivalent:`раз в жизни; уникальный`,register:`neutral`,examples:[[`This is a once-in-a-lifetime chance.`,`Это шанс, который выпадает раз в жизни.`],[`Our trip to Iceland was a once-in-a-lifetime experience.`,`Наша поездка в Исландию была событием, которое бывает раз в жизни.`]],mistake:`Перед существительным слова пишутся через дефис: a once-in-a-lifetime trip.`},{id:`never-in-my-life`,level:`A2`,topic:`Впечатления`,expression:`never in my life`,literal:`никогда в моей жизни`,meaning:`ни разу за всю жизнь; сильное подчёркивание отсутствия опыта`,equivalent:`никогда в жизни`,register:`neutral`,examples:[[`Have you tried snails? — Never in my life!`,`Ты пробовал улиток? — Никогда в жизни!`],[`I have never in my life seen such a big cake.`,`Я никогда в жизни не видел такого большого торта.`]],mistake:`Опыт до сегодняшнего дня выражается Present Perfect: I have never in my life seen it.`},{id:`first-time-for-everything`,level:`A2`,topic:`Впечатления`,expression:`there’s a first time for everything`,literal:`есть первый раз для всего`,meaning:`всё когда-нибудь случается впервые; говорят, когда кто-то делает необычное для себя`,equivalent:`всё бывает в первый раз`,register:`informal`,examples:[[`You cooked dinner? Well, there’s a first time for everything!`,`Ты приготовил ужин? Ну, всё бывает в первый раз!`],[`I have never been late before. There’s a first time for everything.`,`Раньше я никогда не опаздывал. Всё бывает в первый раз.`]],mistake:`Артикль a обязателен: a first time, а не the first time.`},{id:`for-the-first-time`,level:`A2`,topic:`Впечатления`,expression:`for the first time`,literal:`на первый раз`,meaning:`в первый раз за всё время; впервые`,equivalent:`впервые`,register:`neutral`,examples:[[`I tried sushi for the first time last year.`,`Я впервые попробовал суши в прошлом году.`],[`She flew abroad for the first time at the age of twenty.`,`Она впервые полетела за границу в двадцать лет.`]],mistake:`Артикль the обязателен: for the first time, а не for first time.`},{id:`time-is-money`,level:`A2`,topic:`Деньги и время`,expression:`time is money`,literal:`время есть деньги`,meaning:`время ценно, его нельзя тратить зря`,equivalent:`время — деньги`,register:`neutral`,examples:[[`Let’s hurry — time is money.`,`Давайте поторопимся — время — деньги.`],[`My boss always says that time is money.`,`Мой начальник всегда говорит, что время — деньги.`]],mistake:`Артикль не нужен: time is money, а не the time is money.`},{id:`a-waste-of-time`,level:`A2`,topic:`Деньги и время`,expression:`a waste of time`,literal:`отходы времени`,meaning:`занятие, которое не приносит пользы`,equivalent:`пустая трата времени`,register:`neutral`,examples:[[`The meeting was a waste of time.`,`Встреча была пустой тратой времени.`],[`Don’t watch that film. It’s a waste of time.`,`Не смотрите этот фильм. Это пустая трата времени.`]],mistake:`После waste нужен предлог of: a waste of time, а не a waste time.`},{id:`in-no-time`,level:`A2`,topic:`Деньги и время`,expression:`in no time`,literal:`за нет времени`,meaning:`очень быстро, почти мгновенно`,equivalent:`в два счёта`,register:`informal`,examples:[[`Don’t worry, I’ll finish this in no time.`,`Не волнуйтесь, я закончу это в два счёта.`],[`The kids ate all the cake in no time.`,`Дети съели весь торт в два счёта.`]],mistake:`Устойчивая форма — in no time, без артикля и без слова any.`},{id:`save-up-for`,level:`A2`,topic:`Деньги и время`,expression:`save up for`,literal:`сохранить вверх для`,meaning:`откладывать деньги на конкретную цель`,equivalent:`копить на`,register:`neutral`,examples:[[`I’m saving up for a new laptop.`,`Я коплю на новый ноутбук.`],[`They are saving up for a trip to Italy.`,`Они копят на поездку в Италию.`]],mistake:`Цель вводится предлогом for: save up for a bike, а не save up to a bike.`},{id:`cost-a-fortune`,level:`A2`,topic:`Деньги и время`,expression:`cost a fortune`,literal:`стоить удачу`,meaning:`стоить очень дорого`,equivalent:`стоить целое состояние`,register:`informal`,examples:[[`That watch must cost a fortune.`,`Эти часы, должно быть, стоят целое состояние.`],[`Renting a flat here costs a fortune.`,`Аренда квартиры здесь стоит целое состояние.`]],mistake:`Fortune здесь значит «большое богатство», а не «удача».`},{id:`take-it-easy`,level:`A2`,topic:`Здоровье`,expression:`take it easy`,literal:`возьми это легко`,meaning:`не напрягаться, отдыхать и не перегружать себя`,equivalent:`не переутомляйся, отдохни`,register:`informal`,examples:[[`You have a cold. Take it easy this weekend.`,`Ты простыл. Отдохни на этих выходных.`],[`The doctor told him to take it easy.`,`Врач сказал ему не перенапрягаться.`]],mistake:`Это совет отдохнуть, а не «принять это легко». Фраза также бывает прощанием: Take it easy! — Пока, держись!`},{id:`get-well-soon`,level:`A2`,topic:`Здоровье`,expression:`get well soon`,literal:`стань хорошим скоро`,meaning:`пожелание больному человеку скорее поправиться`,equivalent:`скорее выздоравливай`,register:`neutral`,examples:[[`I heard you were sick. Get well soon!`,`Я слышал, ты заболел. Скорее выздоравливай!`],[`We sent her a card that said “Get well soon.”`,`Мы отправили ей открытку «Скорее выздоравливай».`]],mistake:`Говорят get well, а не become well. Глагол get передаёт переход в новое состояние.`},{id:`get-some-rest`,level:`A2`,topic:`Здоровье`,expression:`get some rest`,literal:`получить немного отдыха`,meaning:`отдохнуть, выспаться, дать себе восстановиться`,equivalent:`отдохни как следует`,register:`neutral`,examples:[[`You look tired. You should get some rest.`,`Ты выглядишь усталым. Тебе стоит отдохнуть.`],[`I need to get some rest before the trip.`,`Мне нужно отдохнуть перед поездкой.`]],mistake:`Rest в этом значении неисчисляемое: some rest, не a rest и не rests.`},{id:`whats-the-matter`,level:`A2`,topic:`Здоровье`,expression:`What’s the matter?`,literal:`что есть дело?`,meaning:`вопрос о том, что случилось, почему человеку плохо или тревожно`,equivalent:`что случилось?`,register:`neutral`,examples:[[`You look pale. What’s the matter?`,`Ты бледный. Что случилось?`],[`What’s the matter with your leg?`,`Что с твоей ногой?`]],mistake:`Перед the matter нужен артикль the. Фраза What’s matter? неверна.`},{id:`if-i-were-you`,level:`A2`,topic:`Здоровье`,expression:`If I were you, I’d …`,literal:`если бы я был тобой, я бы …`,meaning:`мягкий способ дать совет, представив себя на месте собеседника`,equivalent:`на твоём месте я бы …`,register:`neutral`,examples:[[`If I were you, I’d see a doctor.`,`На твоём месте я бы сходил к врачу.`],[`If I were you, I’d stay home today.`,`На твоём месте я бы остался сегодня дома.`]],mistake:`Здесь после I ставится were, а не was: If I were you. После I’d идёт начальная форма глагола без to.`},{id:`whats-going-on`,level:`A2`,topic:`Новости и события`,expression:`What’s going on?`,literal:`Что идёт на?`,meaning:`спросить, что происходит прямо сейчас`,equivalent:`Что происходит?`,register:`neutral`,examples:[[`What’s going on? Why is everybody outside?`,`Что происходит? Почему все на улице?`],[`Hey, what’s going on with you today?`,`Эй, что с тобой сегодня творится?`]],mistake:`Нужна форма с going: What’s going on?, а не What goes on?`},{id:`did-you-hear-about`,level:`A2`,topic:`Новости и события`,expression:`Did you hear about …?`,literal:`Ты услышал об …?`,meaning:`начать разговор о свежей новости или событии`,equivalent:`Ты слышал про …?`,register:`neutral`,examples:[[`Did you hear about the accident on Main Street?`,`Ты слышал про аварию на Мейн-стрит?`],[`Did you hear about Sam’s new job?`,`Ты слышал про новую работу Сэма?`]],mistake:`После hear идёт предлог about: Did you hear about it?, а не hear of it в этом значении.`},{id:`who-knows`,level:`A2`,topic:`Новости и события`,expression:`Who knows?`,literal:`Кто знает?`,meaning:`сказать, что ответ неизвестен никому`,equivalent:`Кто его знает? / Неизвестно.`,register:`informal`,examples:[[`Will it rain tomorrow? Who knows?`,`Завтра будет дождь? Кто его знает?`],[`Who knows why he left so early.`,`Кто знает, почему он ушёл так рано.`]],mistake:`Это вопрос к подлежащему: после who глагол без do — Who knows?, а не Who does know?`},{id:`break-the-news`,level:`A2`,topic:`Новости и события`,expression:`break the news`,literal:`сломать новость`,meaning:`первым сообщить человеку важную, часто неприятную новость`,equivalent:`сообщить новость`,register:`neutral`,examples:[[`Who is going to break the news to Dad?`,`Кто сообщит новость папе?`],[`She broke the news to us after dinner.`,`Она сообщила нам новость после ужина.`]],mistake:`Глагол здесь break, а не tell the news: break the news to someone.`},{id:`news-travels-fast`,level:`A2`,topic:`Новости и события`,expression:`News travels fast.`,literal:`Новость путешествует быстро.`,meaning:`о событии быстро узнают все вокруг`,equivalent:`Слухами земля полнится. / Новости разлетаются мгновенно.`,register:`neutral`,examples:[[`We only told Anna, but the whole office knows. News travels fast.`,`Мы сказали только Анне, а знает весь офис. Новости разлетаются мгновенно.`],[`In a small town, news travels fast.`,`В маленьком городке новости разлетаются быстро.`]],mistake:`News — неисчисляемое слово, глагол в форме единственного числа: News travels, а не News travel.`},{id:`by-far-the-best`,level:`A2`,topic:`Сравнения и рекорды`,expression:`by far the best`,literal:`по далёкому лучший`,meaning:`намного лучше всех остальных, с большим отрывом`,equivalent:`безусловно лучший, лучший с огромным отрывом`,register:`neutral`,examples:[[`This is by far the best pizza in town.`,`Это безусловно лучшая пицца в городе.`],[`Maria is by far the fastest runner in our team.`,`Мария намного быстрее всех бегает в нашей команде.`]],mistake:`Усилить превосходную степень можно словом by far (или easily), но не very: нельзя сказать very the best. Порядок: by far the best или the best by far.`},{id:`one-of-the-best`,level:`A2`,topic:`Сравнения и рекорды`,expression:`one of the best`,literal:`один из самых лучших`,meaning:`входит в число лучших, но не обязательно самый лучший`,equivalent:`один из лучших`,register:`neutral`,examples:[[`This is one of the best films of the year.`,`Это один из лучших фильмов года.`],[`She is one of the best teachers I know.`,`Она одна из лучших учителей, которых я знаю.`]],mistake:`После one of the существительное стоит во множественном числе: one of the best films, а не one of the best film. Глагол при этом согласуется с one: One of the best films is on TV.`},{id:`the-best-of-both-worlds`,level:`A2`,topic:`Сравнения и рекорды`,expression:`the best of both worlds`,literal:`лучшее из обоих миров`,meaning:`возможность получить плюсы сразу двух разных вариантов`,equivalent:`и волки сыты, и овцы целы; взять лучшее от обоих вариантов`,register:`neutral`,examples:[[`I work from home two days a week, so I get the best of both worlds.`,`Я работаю из дома два дня в неделю, так что у меня есть плюсы обоих вариантов.`],[`Our flat is near the park and the city center. It’s the best of both worlds.`,`Наша квартира рядом с парком и с центром города. Это лучшее от обоих вариантов.`]],mistake:`Устойчивая форма: the best of both worlds, с артиклем the и во множественном числе worlds.`},{id:`make-the-most-of`,level:`A2`,topic:`Сравнения и рекорды`,expression:`make the most of`,literal:`сделать самое из`,meaning:`использовать что-то по максимуму, получить как можно больше пользы или удовольствия`,equivalent:`выжать максимум из, не упустить возможность`,register:`neutral`,examples:[[`Let’s make the most of the sunny weather.`,`Давайте используем солнечную погоду по максимуму.`],[`You’re in London for two days, so make the most of it.`,`Вы в Лондоне всего два дня, так что используйте их по максимуму.`]],mistake:`Нужен артикль the и слово most: make the most of, а не make most of или make the best of (это другое выражение: «извлечь лучшее из плохой ситуации»).`},{id:`ill-give-you-a-hand`,level:`A2`,topic:`Обещания и предложения помощи`,expression:`I’ll give you a hand`,literal:`я дам тебе руку`,meaning:`предложить помощь, особенно в физической работе или в деле`,equivalent:`я тебе помогу, подсоблю`,register:`informal`,examples:[[`That box looks heavy. I’ll give you a hand.`,`Эта коробка выглядит тяжёлой. Я тебе помогу.`],[`Can you give me a hand with the dishes?`,`Поможешь мне с посудой?`]],mistake:`Говорят give a hand, а не give a arm или give hands.`},{id:`cross-my-heart`,level:`A2`,topic:`Обещания и предложения помощи`,expression:`cross my heart`,literal:`перекрестить моё сердце`,meaning:`подчеркнуть, что вы говорите правду или точно выполните обещание`,equivalent:`честное слово, зуб даю`,register:`informal`,examples:[[`I won’t tell anyone, cross my heart.`,`Я никому не скажу, честное слово.`],[`I’ll be there at eight, cross my heart.`,`Я буду там в восемь, зуб даю.`]],mistake:`Устойчивая форма — cross my heart, с притяжательным my, а не cross the heart.`},{id:`ill-think-about-it`,level:`A2`,topic:`Обещания и предложения помощи`,expression:`I’ll think about it`,literal:`я подумаю об этом`,meaning:`не отвечать сразу на предложение и взять время на размышление`,equivalent:`я подумаю`,register:`neutral`,examples:[[`— Do you want to join us? — I’ll think about it.`,`— Хочешь присоединиться к нам? — Я подумаю.`],[`Thanks for the offer. I’ll think about it.`,`Спасибо за предложение. Я подумаю.`]],mistake:`Решение в момент ответа — will, а не Present Simple: I’ll think, не I think about it.`},{id:`leave-it-to-me`,level:`A2`,topic:`Обещания и предложения помощи`,expression:`leave it to me`,literal:`оставь это мне`,meaning:`взять дело на себя и успокоить собеседника`,equivalent:`предоставь это мне, я сам займусь`,register:`neutral`,examples:[[`Don’t worry about the tickets. Leave it to me.`,`Не беспокойтесь о билетах. Предоставьте это мне.`],[`I’ll call the hotel. Leave it to me.`,`Я позвоню в отель. Положитесь на меня.`]],mistake:`После to идёт me, а не I: leave it to me, не leave it to I.`},{id:`settle-down`,level:`A2`,topic:`Жизненные события`,expression:`settle down`,literal:`усесться вниз`,meaning:`начать спокойную жизнь на одном месте: завести семью, купить дом, найти постоянную работу`,equivalent:`остепениться, обосноваться`,register:`neutral`,examples:[[`They got married and settled down in Boston.`,`Они поженились и обосновались в Бостоне.`],[`He has travelled a lot, but now he wants to settle down.`,`Он много путешествовал, но теперь хочет остепениться.`]],mistake:`Без предлога: settle down, не settle on down. Для места используйте in: settle down in Boston.`},{id:`a-while-back`,level:`A2`,topic:`Жизненные события`,expression:`a while back`,literal:`некоторое время назад (сзади)`,meaning:`какое-то время назад, не очень точно`,equivalent:`как-то раз, некоторое время назад`,register:`informal`,examples:[[`I met her a while back at a conference.`,`Я познакомился с ней некоторое время назад на конференции.`],[`We moved here a while back.`,`Мы переехали сюда какое-то время назад.`]],mistake:`Как и ago, a while back называет прошлое время, поэтому нужен Past Simple: I met her a while back, а не I have met her a while back.`}],"../../../content/phrases/B1.ts":[{id:`make-a-decision`,level:`B1`,topic:`Решения`,expression:`make a decision`,literal:`сделать решение`,meaning:`принять решение, сделать выбор`,equivalent:`принять решение`,register:`neutral`,examples:[[`We need to make a decision by Friday.`,`Нам нужно принять решение до пятницы.`],[`It was a hard decision to make, but I don’t regret it.`,`Решение далось тяжело, но я не жалею.`]],mistake:`Не accept a decision: accept — «согласиться с чужим решением». Take a decision встречается в британском английском, в американском своё решение — make a decision.`},{id:`give-up`,level:`B1`,topic:`Решения`,expression:`give up`,literal:`дать вверх`,meaning:`бросить, перестать что-то делать; сдаться`,equivalent:`бросить, сдаться`,register:`neutral`,examples:[[`My uncle gave up smoking last year.`,`Мой дядя бросил курить в прошлом году.`],[`Don’t give up — you’re almost there!`,`Не сдавайтесь — вы почти у цели!`]],mistake:`После give up глагол стоит с -ing: give up smoking, не give up to smoke.`},{id:`come-up-with`,level:`B1`,topic:`Решения`,expression:`come up with`,literal:`прийти вверх с`,meaning:`придумать идею, план, решение`,equivalent:`придумать, предложить`,register:`neutral`,examples:[[`She came up with a great idea for the party.`,`Она придумала отличную идею для вечеринки.`]],mistake:`Не invent: invent — изобрести устройство. И не think out — это «продумать в деталях». Идею или план придумывают — come up with (with обязателен).`},{id:`on-second-thought`,level:`B1`,topic:`Решения`,expression:`on second thought`,literal:`на второй мысли`,meaning:`передумав, после размышления (меняя только что сказанное)`,equivalent:`хотя нет, пожалуй; если подумать`,register:`informal`,examples:[[`I’ll have the pasta. On second thought, I’ll get the salad.`,`Я возьму пасту. Хотя нет, пожалуй, возьму салат.`]],mistake:`В американском варианте — thought в единственном числе; в британском — on second thoughts.`},{id:`turn-down`,level:`B1`,topic:`Решения`,expression:`turn down`,literal:`повернуть вниз`,meaning:`отказаться от предложения, отклонить; также убавить громкость`,equivalent:`отказаться, отклонить`,register:`neutral`,examples:[[`He turned down the job because the pay was too low.`,`Он отказался от этой работы, потому что платили слишком мало.`],[`They offered me a ride, but I turned it down.`,`Мне предложили подвезти, но я отказался.`]],mistake:`Местоимение ставится между частями: turn it down, не turn down it.`},{id:`get-along-with`,level:`B1`,topic:`Отношения`,expression:`get along with`,literal:`получить вдоль с`,meaning:`ладить, иметь хорошие отношения с кем-то`,equivalent:`ладить, находить общий язык`,register:`neutral`,examples:[[`I get along well with my coworkers.`,`Я хорошо лажу с коллегами.`],[`Do you get along with your sister?`,`Вы ладите с сестрой?`]],mistake:`Предлог with обязателен перед тем, с кем ладят. В британском английском чаще get on with.`},{id:`keep-in-touch`,level:`B1`,topic:`Отношения`,expression:`keep in touch`,literal:`держать в касании`,meaning:`поддерживать связь, не теряться`,equivalent:`оставаться на связи, не пропадать`,register:`neutral`,examples:[[`We moved to different cities, but we still keep in touch.`,`Мы переехали в разные города, но до сих пор общаемся.`],[`It was great to see you. Let’s keep in touch!`,`Рад был тебя видеть. Не пропадай!`]],mistake:`Не stay on connection (дословно «на связи»). Говорят keep in touch или stay in touch с предлогом in.`},{id:`count-on`,level:`B1`,topic:`Отношения`,expression:`count on`,literal:`считать на`,meaning:`полагаться на кого-то, рассчитывать на помощь`,equivalent:`рассчитывать на, положиться на`,register:`neutral`,examples:[[`You can always count on me if you need help.`,`Если понадобится помощь, всегда можешь на меня рассчитывать.`]],mistake:`Предлог — on, как в русском «на»; не count for и не count at.`},{id:`catch-a-cold`,level:`B1`,topic:`Самочувствие`,expression:`catch a cold`,literal:`поймать холод`,meaning:`заболеть простудой`,equivalent:`простудиться`,register:`neutral`,examples:[[`Take an umbrella, or you’ll catch a cold.`,`Возьми зонт, а то простудишься.`],[`I caught a cold on vacation.`,`Я простудился в отпуске.`]],mistake:`Не take a cold. И не путайте с get cold — это «замёрзнуть». Простудиться — catch a cold или get a cold.`},{id:`get-over`,level:`B1`,topic:`Самочувствие`,expression:`get over`,literal:`получить над`,meaning:`оправиться после болезни, расставания или неприятности`,equivalent:`прийти в себя, пережить, оправиться`,register:`neutral`,examples:[[`It took me two weeks to get over the flu.`,`Мне понадобилось две недели, чтобы оправиться от гриппа.`],[`She still hasn’t gotten over the breakup.`,`Она до сих пор не пережила расставание.`]],mistake:`Дополнение идёт сразу после over, без from: get over the flu, не get over from the flu.`},{id:`feel-like`,level:`B1`,topic:`Самочувствие`,expression:`feel like`,literal:`чувствовать как`,meaning:`хотеть чего-то, быть в настроении что-то делать`,equivalent:`хотеться, быть настроенным`,register:`informal`,examples:[[`I don’t feel like cooking tonight. Let’s order pizza.`,`Мне сегодня не хочется готовить. Давай закажем пиццу.`],[`Do you feel like going for a walk?`,`Хочешь прогуляться?`]],mistake:`После feel like глагол стоит с -ing: feel like going, не feel like to go.`},{id:`run-out-of`,level:`B1`,topic:`Повседневные дела`,expression:`run out of`,literal:`выбежать из`,meaning:`израсходовать что-то до конца, остаться без чего-то`,equivalent:`закончиться (у кого-то)`,register:`neutral`,examples:[[`We’ve run out of coffee. I’ll buy some on my way home.`,`У нас закончился кофе. Куплю по дороге домой.`],[`We ran out of gas on the highway.`,`У нас кончился бензин на трассе.`]],mistake:`По-русски «кофе закончился», а по-английски подлежащее — тот, у кого закончилось: We’ve run out of coffee. Перед существительным нужен of.`},{id:`take-part-in`,level:`B1`,topic:`Повседневные дела`,expression:`take part in`,literal:`взять часть в`,meaning:`участвовать в чём-то`,equivalent:`принимать участие`,register:`neutral`,examples:[[`More than 200 students took part in the race.`,`В забеге приняли участие более 200 студентов.`]],mistake:`Предлог — in, не at и не on: take part in a contest.`},{id:`pay-attention-to`,level:`B1`,topic:`Повседневные дела`,expression:`pay attention to`,literal:`заплатить внимание к`,meaning:`обращать внимание, внимательно следить`,equivalent:`обращать внимание`,register:`neutral`,examples:[[`Please pay attention to the instructions.`,`Пожалуйста, обратите внимание на инструкции.`],[`Sorry, I wasn’t paying attention.`,`Извините, я отвлёкся.`]],mistake:`Глагол — pay, не turn и не give (дословно «обратить»). Предлог — to, не on.`},{id:`figure-out`,level:`B1`,topic:`Повседневные дела`,expression:`figure out`,literal:`фигурировать наружу`,meaning:`понять, разобраться, найти решение`,equivalent:`разобраться, сообразить`,register:`informal`,examples:[[`I can’t figure out how this coffee machine works.`,`Не могу разобраться, как работает эта кофемашина.`],[`Don’t worry, we’ll figure it out.`,`Не волнуйся, разберёмся.`]],mistake:`Местоимение ставится в середину: figure it out, не figure out it.`},{id:`its-not-worth-it`,level:`B1`,topic:`Оценка и мнение`,expression:`it’s not worth it`,literal:`это не стоящее этого`,meaning:`это не оправдывает усилий, денег или времени`,equivalent:`оно того не стоит`,register:`neutral`,examples:[[`Don’t argue with him — it’s not worth it.`,`Не спорь с ним — оно того не стоит.`],[`I could take a taxi, but it’s only a ten-minute walk — it’s not worth it.`,`Можно взять такси, но тут десять минут пешком — оно того не стоит.`]],mistake:`Не it doesn’t cost it: cost — только о цене. После worth глагол стоит с -ing: it’s not worth waiting.`},{id:`make-sense`,level:`B1`,topic:`Оценка и мнение`,expression:`make sense`,literal:`делать смысл`,meaning:`быть логичным и понятным`,equivalent:`иметь смысл, быть понятным`,register:`neutral`,examples:[[`Your plan makes sense. Let’s try it.`,`Ваш план разумный. Давайте попробуем.`],[`This sentence doesn’t make sense.`,`В этом предложении нет смысла.`]],mistake:`Не have sense (дословно «иметь смысл»). Говорят make sense.`},{id:`no-wonder`,level:`B1`,topic:`Оценка и мнение`,expression:`no wonder`,literal:`нет чуда`,meaning:`неудивительно, понятно почему`,equivalent:`неудивительно, то-то`,register:`informal`,examples:[[`You worked all night? No wonder you’re tired.`,`Ты работал всю ночь? Неудивительно, что ты устал.`]],mistake:`Не путайте с I wonder — «интересно, хотел бы я знать»: I wonder why he left.`}],"../../../content/phrases/B2.ts":[{id:`pull-yourself-together`,level:`B2`,topic:`Эмоции`,expression:`pull yourself together`,literal:`стяни себя вместе`,meaning:`успокоиться и собраться после сильных эмоций`,equivalent:`возьми себя в руки`,register:`informal`,examples:[[`Pull yourself together — the interview starts in five minutes.`,`Возьми себя в руки — собеседование через пять минут.`]],mistake:`Устойчивая форма — pull yourself together, не put.`},{id:`get-on-someones-nerves`,level:`B2`,topic:`Эмоции`,expression:`get on someone’s nerves`,literal:`попасть на чьи-то нервы`,meaning:`постоянно и сильно раздражать`,equivalent:`действовать на нервы`,register:`informal`,examples:[[`His constant complaining is starting to get on my nerves.`,`Его вечное нытьё начинает действовать мне на нервы.`]],mistake:`Глагол — get: калька с «действовать на нервы» или «играть на нервах» (act, play) по-английски не работает.`},{id:`the-last-straw`,level:`B2`,topic:`Эмоции`,expression:`the last straw`,literal:`последняя соломинка`,meaning:`последняя из череды неприятностей, после которой терпение заканчивается`,equivalent:`последняя капля`,register:`neutral`,examples:[[`He was late again and didn’t even apologize. That was the last straw.`,`Он снова опоздал и даже не извинился. Это стало последней каплей.`]],mistake:`Не the last drop: в английской пословице спину верблюду ломает соломинка (straw), а не капля.`},{id:`blow-off-steam`,level:`B2`,topic:`Эмоции`,expression:`blow off steam`,literal:`сдуть пар`,meaning:`дать выход накопившемуся напряжению или злости`,equivalent:`выпустить пар`,register:`informal`,examples:[[`After a stressful week, I go for a long run to blow off steam.`,`После напряжённой недели я выхожу на долгую пробежку, чтобы выпустить пар.`]],mistake:`Вариант let off steam тоже правильный и типичен для британского английского. Не blow out steam.`},{id:`cut-corners`,level:`B2`,topic:`Работа`,expression:`cut corners`,literal:`срезать углы`,meaning:`делать что-то наспех или дёшево в ущерб качеству`,equivalent:`халтурить, делать спустя рукава`,register:`neutral`,examples:[[`The builders cut corners, and now the roof leaks every time it rains.`,`Строители схалтурили, и теперь крыша протекает при каждом дожде.`],[`Never cut corners when it comes to safety.`,`Когда речь идёт о безопасности, нельзя халтурить.`]],mistake:`Только во множественном числе и без артикля: cut corners. Cut the corner — буквально срезать путь на повороте.`},{id:`call-it-a-day`,level:`B2`,topic:`Работа`,expression:`call it a day`,literal:`назвать это днём`,meaning:`закончить работу на сегодня`,equivalent:`на сегодня хватит`,register:`informal`,examples:[[`It’s almost seven. Let’s call it a day and finish the slides tomorrow.`,`Уже почти семь. На сегодня хватит, слайды доделаем завтра.`]],mistake:`Поздно вечером, особенно после вечеринки или посиделок, говорят call it a night.`},{id:`hit-the-nail-on-the-head`,level:`B2`,topic:`Работа`,expression:`hit the nail on the head`,literal:`ударить гвоздь по голове`,meaning:`точно назвать суть проблемы`,equivalent:`попасть в точку`,register:`neutral`,examples:[[`You hit the nail on the head: the real problem is the budget, not the deadline.`,`Вы попали в точку: настоящая проблема — бюджет, а не сроки.`]],mistake:`Не hit the point: дословный перевод «попасть в точку» по-английски не звучит.`},{id:`get-the-ball-rolling`,level:`B2`,topic:`Работа`,expression:`get the ball rolling`,literal:`заставить мяч катиться`,meaning:`начать какое-то дело, сделать первый шаг`,equivalent:`сдвинуть дело с мёртвой точки, положить начало`,register:`informal`,examples:[[`Let me get the ball rolling with a quick update from our team.`,`Давайте я начну с короткого отчёта нашей команды.`]]},{id:`think-outside-the-box`,level:`B2`,topic:`Работа`,expression:`think outside the box`,literal:`думать снаружи коробки`,meaning:`подходить к задаче нестандартно, творчески`,equivalent:`мыслить нестандартно, выйти за рамки`,register:`neutral`,examples:[[`We need someone who can think outside the box and find new customers.`,`Нам нужен человек, который умеет мыслить нестандартно и найдёт новых клиентов.`]],mistake:`В американском английском — outside the box. Out-of-the-box о технике значит «готовый к работе сразу после покупки».`},{id:`break-the-ice`,level:`B2`,topic:`Отношения`,expression:`break the ice`,literal:`сломать лёд`,meaning:`снять неловкость в начале знакомства или разговора`,equivalent:`растопить лёд`,register:`neutral`,examples:[[`Our teacher started the first class with a game to break the ice.`,`Преподаватель начал первое занятие с игры, чтобы растопить лёд.`]],mistake:`По-русски лёд растапливают, а по-английски ломают: break the ice, не melt the ice.`},{id:`see-eye-to-eye`,level:`B2`,topic:`Отношения`,expression:`see eye to eye`,literal:`видеть глаз в глаз`,meaning:`полностью соглашаться, одинаково смотреть на вещи`,equivalent:`сходиться во взглядах`,register:`neutral`,examples:[[`My dad and I don’t always see eye to eye on politics.`,`Мы с папой не всегда сходимся во взглядах на политику.`]],mistake:`Чаще всего в отрицании: we don’t see eye to eye. Не путайте с выражением «смотреть в глаза» — это look someone in the eye.`},{id:`give-someone-the-benefit-of-the-doubt`,level:`B2`,topic:`Отношения`,expression:`give someone the benefit of the doubt`,literal:`дать кому-то выгоду сомнения`,meaning:`поверить человеку, пока нет доказательств обратного`,equivalent:`поверить на слово, не судить сгоряча`,register:`neutral`,examples:[[`He’s never lied to me before, so I’ll give him the benefit of the doubt.`,`Раньше он мне никогда не врал, так что я поверю ему на слово.`]]},{id:`have-someones-back`,level:`B2`,topic:`Отношения`,expression:`have someone’s back`,literal:`иметь чью-то спину`,meaning:`поддерживать человека и защищать его в трудной ситуации`,equivalent:`прикрывать, быть на чьей-то стороне`,register:`informal`,examples:[[`Don’t worry about the meeting — I’ve got your back.`,`Не переживай из-за совещания — я тебя прикрою.`]],mistake:`Не путайте с behind someone’s back — «за спиной», тайком от человека.`},{id:`sleep-on-it`,level:`B2`,topic:`Повседневные ситуации`,expression:`sleep on it`,literal:`поспать на этом`,meaning:`отложить важное решение до завтра, чтобы спокойно его обдумать`,equivalent:`утро вечера мудренее; подумать до завтра`,register:`neutral`,examples:[[`You don’t have to decide right now. Sleep on it and call me tomorrow.`,`Не обязательно решать прямо сейчас. Подумайте до завтра и позвоните мне.`]],mistake:`Только с on. Sleep with it звучит как «переспать с кем-то», а sleep over — «переночевать».`},{id:`out-of-the-blue`,level:`B2`,topic:`Повседневные ситуации`,expression:`out of the blue`,literal:`из синевы`,meaning:`совершенно неожиданно, без предупреждения`,equivalent:`как гром среди ясного неба, ни с того ни с сего`,register:`neutral`,examples:[[`My old roommate called me out of the blue after ten years.`,`Спустя десять лет мне ни с того ни с сего позвонил бывший сосед по комнате.`]]},{id:`under-the-weather`,level:`B2`,topic:`Повседневные ситуации`,expression:`under the weather`,literal:`под погодой`,meaning:`слегка нездоров, неважно себя чувствует`,equivalent:`расклеиться, неважно себя чувствовать`,register:`informal`,examples:[[`I’m feeling a little under the weather, so I’ll work from home today.`,`Я что-то расклеился, так что сегодня поработаю из дома.`]],mistake:`Это о лёгком недомогании, не о серьёзной болезни, и к погоде отношения не имеет.`},{id:`a-piece-of-cake`,level:`B2`,topic:`Повседневные ситуации`,expression:`a piece of cake`,literal:`кусок торта`,meaning:`что-то очень лёгкое`,equivalent:`проще простого, раз плюнуть`,register:`informal`,examples:[[`I was nervous about the driving test, but it was a piece of cake.`,`Я волновался перед экзаменом по вождению, а оказалось — проще простого.`]],mistake:`С артиклем a: it was a piece of cake, не it was piece of cake.`},{id:`keep-an-eye-on`,level:`B2`,topic:`Повседневные ситуации`,expression:`keep an eye on`,literal:`держать глаз на`,meaning:`присматривать за кем-то или чем-то, следить`,equivalent:`присмотреть, не спускать глаз`,register:`neutral`,examples:[[`Could you keep an eye on my bag while I grab a coffee?`,`Присмотрите, пожалуйста, за моей сумкой, пока я схожу за кофе.`]],mistake:`В значении «присмотреть» — keep an eye on (один глаз, с артиклем). Keep your eyes on — буквально не отрывать взгляда: keep your eyes on the road.`}],"../../../content/phrases/C1.ts":[{id:`the-elephant-in-the-room`,level:`C1`,topic:`Трудные разговоры`,expression:`the elephant in the room`,literal:`слон в комнате`,meaning:`очевидная острая проблема, которую все видят, но обходят молчанием`,equivalent:`неудобная тема, о которой все молчат`,register:`neutral`,examples:[[`Let’s address the elephant in the room: we’re three months behind schedule.`,`Давайте скажем вслух то, о чём все молчат: мы отстаём от графика на три месяца.`]],mistake:`Не путайте с «слона-то я и не приметил» (не заметить главного): в английской идиоме проблему видят все, но молчат о ней.`},{id:`beat-around-the-bush`,level:`C1`,topic:`Трудные разговоры`,expression:`beat around the bush`,literal:`бить вокруг куста`,meaning:`говорить уклончиво, не переходя к сути`,equivalent:`ходить вокруг да около`,register:`informal`,examples:[[`Stop beating around the bush and tell me what happened.`,`Хватит ходить вокруг да около — скажи, что случилось.`]],mistake:`Чаще всего звучит с отрицанием или stop: Don’t beat around the bush. Британский вариант — beat about the bush.`},{id:`read-between-the-lines`,level:`C1`,topic:`Трудные разговоры`,expression:`read between the lines`,literal:`читать между линиями`,meaning:`улавливать скрытый смысл, который прямо не высказан`,equivalent:`читать между строк`,register:`neutral`,examples:[[`The press release sounds upbeat, but if you read between the lines, the company is in trouble.`,`Пресс-релиз звучит бодро, но если читать между строк, у компании проблемы.`]],mistake:`Редкий случай, когда русский и английский образ совпадают. Предлог — between, не among.`},{id:`play-devils-advocate`,level:`C1`,topic:`Трудные разговоры`,expression:`play devil’s advocate`,literal:`играть адвоката дьявола`,meaning:`намеренно отстаивать противоположную точку зрения, чтобы проверить аргументы`,equivalent:`выступить адвокатом дьявола, нарочно возразить`,register:`neutral`,examples:[[`Let me play devil’s advocate for a moment: what if customers don’t actually want this feature?`,`Позвольте мне побыть адвокатом дьявола: а что, если клиентам эта функция на самом деле не нужна?`],[`I agree with you — I’m just playing devil’s advocate.`,`Я с вами согласен — просто нарочно возражаю.`]],mistake:`Глагол — play, не make и не do: I’m just playing devil’s advocate.`},{id:`bite-the-bullet`,level:`C1`,topic:`Решения и усилия`,expression:`bite the bullet`,literal:`укусить пулю`,meaning:`решиться на неприятное, но неизбежное действие`,equivalent:`стиснуть зубы и сделать, собраться с духом`,register:`informal`,examples:[[`I finally bit the bullet and told my boss I was leaving.`,`Я наконец собрался с духом и сказал начальнику, что ухожу.`]],mistake:`Не путайте с bite the dust («потерпеть крах, сломаться») и bite your tongue («промолчать»).`},{id:`go-the-extra-mile`,level:`C1`,topic:`Решения и усилия`,expression:`go the extra mile`,literal:`пройти лишнюю милю`,meaning:`сделать больше, чем требуется или ожидается`,equivalent:`сделать больше положенного, не жалеть сил`,register:`neutral`,examples:[[`Our best nurses always go the extra mile for their patients.`,`Наши лучшие медсёстры всегда делают для пациентов больше, чем положено.`]],mistake:`Форма застывшая: the extra mile. Mile не меняют на kilometer.`},{id:`a-blessing-in-disguise`,level:`C1`,topic:`Решения и усилия`,expression:`a blessing in disguise`,literal:`благословение под маской`,meaning:`неприятность, которая в итоге обернулась к лучшему`,equivalent:`не было бы счастья, да несчастье помогло`,register:`neutral`,examples:[[`Missing that flight turned out to be a blessing in disguise: I met my future business partner at the airport.`,`Не было бы счастья, да несчастье помогло: опоздав на рейс, я познакомился в аэропорту с будущим деловым партнёром.`]],mistake:`Обычно с be или turn out to be: It turned out to be a blessing in disguise.`},{id:`the-ball-is-in-your-court`,level:`C1`,topic:`Решения и усилия`,expression:`the ball is in your court`,literal:`мяч на твоей площадке`,meaning:`теперь ваш ход: решение или следующий шаг за вами`,equivalent:`слово за вами, теперь ваш ход`,register:`neutral`,examples:[[`We’ve made our final offer, so the ball is in their court now.`,`Мы сделали последнее предложение, теперь ход за ними.`]],mistake:`Местоимение меняется по смыслу: the ball is in my / your / their court.`},{id:`a-far-cry-from`,level:`C1`,topic:`Оценка и сравнение`,expression:`a far cry from`,literal:`далёкий крик от`,meaning:`совсем не похоже на что-то, разительно отличается`,equivalent:`небо и земля, совсем не то, что…`,register:`neutral`,examples:[[`The final version of the app is a far cry from the prototype we saw last year.`,`Финальная версия приложения — небо и земля по сравнению с прототипом, который мы видели в прошлом году.`]],mistake:`Предлог обязателен — from: a far cry from the original, не a far cry of.`},{id:`a-double-edged-sword`,level:`C1`,topic:`Оценка и сравнение`,expression:`a double-edged sword`,literal:`обоюдоострый меч`,meaning:`то, что приносит и пользу, и вред`,equivalent:`палка о двух концах`,register:`neutral`,examples:[[`For small businesses, social media is a double-edged sword.`,`Для малого бизнеса соцсети — палка о двух концах.`]],mistake:`Русское «палка о двух концах» дословно не переводится: a stick with two ends носитель не поймёт.`},{id:`the-jury-is-still-out`,level:`C1`,topic:`Оценка и сравнение`,expression:`the jury is still out`,literal:`присяжные всё ещё вне зала`,meaning:`вопрос пока не решён, однозначного вывода нет`,equivalent:`вопрос остаётся открытым, пока неясно`,register:`neutral`,examples:[[`The jury is still out on whether remote work makes teams more productive.`,`Пока неясно, повышает ли удалённая работа продуктивность команд.`]],mistake:`О чём идёт речь, вводят предлогом on: the jury is still out on something.`},{id:`take-something-with-a-grain-of-salt`,level:`C1`,topic:`Оценка и сравнение`,expression:`take something with a grain of salt`,literal:`брать что-то с крупинкой соли`,meaning:`относиться к сведениям скептически, не принимать всё за чистую монету`,equivalent:`относиться с долей скепсиса, делить на два`,register:`neutral`,examples:[[`Take those online reviews with a grain of salt — some of them are paid for.`,`Относитесь к отзывам в интернете с долей скепсиса: часть из них заказные.`]],mistake:`Американский вариант — with a grain of salt, британский — with a pinch of salt.`},{id:`by-and-large`,level:`C1`,topic:`Обобщение и вывод`,expression:`by and large`,literal:`около и крупно`,meaning:`в целом, если не вдаваться в детали`,equivalent:`в целом, по большому счёту`,register:`neutral`,examples:[[`By and large, the new system works well, although a few bugs remain.`,`В целом новая система работает хорошо, хотя несколько ошибок осталось.`]],mistake:`Порядок слов неизменен: by and large, не large and by. By and by — другое, «вскоре».`},{id:`for-all-intents-and-purposes`,level:`C1`,topic:`Обобщение и вывод`,expression:`for all intents and purposes`,literal:`для всех намерений и целей`,meaning:`практически, по существу`,equivalent:`по сути дела, фактически`,register:`formal`,examples:[[`The contract hasn’t been signed yet, but for all intents and purposes, the deal is done.`,`Контракт ещё не подписан, но по сути сделка заключена.`]],mistake:`Британский вариант — to all intents and purposes. Ошибка на слух — for all intensive purposes.`},{id:`at-the-end-of-the-day`,level:`C1`,topic:`Обобщение и вывод`,expression:`at the end of the day`,literal:`в конце дня`,meaning:`в конечном счёте, если говорить о главном`,equivalent:`в конце концов, в конечном счёте`,register:`informal`,examples:[[`At the end of the day, it’s your decision, not mine.`,`В конечном счёте решать вам, а не мне.`]],mistake:`Речь не о времени суток: фраза подводит итог рассуждению. В официальном письме уместнее ultimately.`},{id:`be-that-as-it-may`,level:`C1`,topic:`Обобщение и вывод`,expression:`be that as it may`,literal:`будь это как оно может`,meaning:`признать довод собеседника и всё же перейти к возражению`,equivalent:`как бы то ни было, и всё же`,register:`formal`,examples:[[`The budget is tight. Be that as it may, we cannot cut safety training.`,`Бюджет ограничен. И всё же сокращать обучение технике безопасности мы не можем.`]],mistake:`Застывшая форма с сослагательным be: не That being as it may и не Be it as it may.`},{id:`first-and-foremost`,level:`C1`,topic:`Обобщение и вывод`,expression:`first and foremost`,literal:`первый и передний`,meaning:`прежде всего, в первую очередь`,equivalent:`прежде всего, в первую очередь`,register:`neutral`,examples:[[`First and foremost, I’d like to thank our volunteers.`,`Прежде всего я хотел бы поблагодарить наших волонтёров.`]],mistake:`Устойчивая форма — first and foremost, не firstly and foremost.`}]}),n=e.flatMap(e=>t[`../../../content/phrases/${e}.ts`]??[]),r=new Map(n.map(e=>[e.id,e]));function i(e){return r.get(e)}function a(e,{level:t,query:n}){let r=n.trim().toLowerCase();return e.filter(e=>(t===`all`||e.level===t)&&(!r||[e.expression,e.meaning,e.equivalent,e.topic].some(e=>e.toLowerCase().includes(r))))}function o(e){let t=new Map;for(let n of e){let e=`${n.level} · ${n.topic}`;t.set(e,[...t.get(e)??[],n])}return[...t].map(([e,t])=>({title:e,phrases:t}))}function s(e){return new Set(e.flatMap(e=>e.type===`phrase`&&e.lessonId?[e.id]:[]))}export{n as a,s as i,i as n,o as r,a as t};